import { useState, useEffect, useRef } from "react";

export interface ComboboxOption {
  value: string;
  label: string;
  sublabel?: string;
}

interface ComboboxProps {
  value: string;
  onChange: (value: string) => void;
  placeholder?: string;
  searchPlaceholder?: string;
  emptyText?: string;
  options?: ComboboxOption[];
  fetcher?: (queryStr: string) => Promise<ComboboxOption[]>;
  disabled?: boolean;
  className?: string;
}

export function Combobox({
  value,
  onChange,
  placeholder = "Select option...",
  searchPlaceholder = "Search...",
  emptyText = "No options found.",
  options: staticOptions,
  fetcher,
  disabled = false,
  className = "",
}: ComboboxProps) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [options, setOptions] = useState<ComboboxOption[]>(staticOptions || []);
  const [loading, setLoading] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (staticOptions) {
      setOptions(staticOptions);
    }
  }, [staticOptions]);

  useEffect(() => {
    if (!fetcher) return;
    let active = true;
    setLoading(true);
    fetcher(query)
      .then((res) => {
        if (active) {
          setOptions(res);
          setLoading(false);
        }
      })
      .catch(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
    };
  }, [query, fetcher]);

  // Click outside listener
  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const selectedOption = options.find((o) => o.value === value);

  const filteredOptions = fetcher
    ? options
    : options.filter(
        (o) =>
          o.label.toLowerCase().includes(query.toLowerCase()) ||
          (o.sublabel && o.sublabel.toLowerCase().includes(query.toLowerCase()))
      );

  return (
    <div ref={containerRef} className={`relative w-full ${className}`}>
      <button
        type="button"
        disabled={disabled}
        onClick={() => setOpen((prev) => !prev)}
        className="flex h-10 w-full items-center justify-between rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white placeholder:text-gray-500 focus:outline-none focus:ring-2 focus:ring-indigo-500 disabled:cursor-not-allowed disabled:opacity-50"
      >
        <span className="truncate">
          {selectedOption ? selectedOption.label : placeholder}
        </span>
        <svg
          xmlns="http://www.w3.org/2000/svg"
          viewBox="0 0 20 20"
          fill="currentColor"
          className="h-4 w-4 shrink-0 text-gray-400"
        >
          <path
            fillRule="evenodd"
            d="M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z"
            clipRule="evenodd"
          />
        </svg>
      </button>

      {open && (
        <div className="absolute z-50 mt-1 max-h-60 w-full overflow-auto rounded-xl border border-white/10 bg-gray-900 p-1 shadow-2xl text-white backdrop-blur">
          <div className="p-1">
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder={searchPlaceholder}
              className="w-full rounded-md border border-white/10 bg-white/5 px-2.5 py-1.5 text-xs text-white placeholder:text-gray-500 focus:outline-none focus:ring-1 focus:ring-indigo-500"
              autoFocus
            />
          </div>
          <div className="mt-1 divide-y divide-white/5">
            {loading ? (
              <div className="py-4 text-center text-xs text-gray-400">Loading options...</div>
            ) : filteredOptions.length === 0 ? (
              <div className="py-4 text-center text-xs text-gray-500">{emptyText}</div>
            ) : (
              filteredOptions.map((opt) => (
                <button
                  key={opt.value}
                  type="button"
                  onClick={() => {
                    onChange(opt.value);
                    setOpen(false);
                    setQuery("");
                  }}
                  className={`flex w-full flex-col text-left px-3 py-2 text-xs transition-colors rounded-md ${
                    opt.value === value
                      ? "bg-indigo-600 text-white font-medium"
                      : "hover:bg-white/10 text-gray-300 hover:text-white"
                  }`}
                >
                  <span className="font-medium">{opt.label}</span>
                  {opt.sublabel && (
                    <span className="text-[10px] text-gray-400">{opt.sublabel}</span>
                  )}
                </button>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
}

import { createContext, useContext, useState, type ReactNode } from "react";
import { currentAcademicYear, getAcademicYears, type AcademicYear } from "@/types";
import { useAuth } from "@/contexts/AuthContext";

interface AcademicYearContextType {
  activeYear: AcademicYear;
  setActiveYear: (year: AcademicYear) => void;
  allYears: AcademicYear[];
}

const AcademicYearContext = createContext<AcademicYearContextType | undefined>(undefined);

export function AcademicYearProvider({ children }: { children: ReactNode }) {
  const { schoolId } = useAuth();

  // Persist selected year per school in localStorage
  const storageKey = `activeYear_${schoolId}`;
  const saved = typeof window !== "undefined" ? localStorage.getItem(storageKey) : null;

  const [activeYear, setActiveYearState] = useState<AcademicYear>(
    saved ?? currentAcademicYear()
  );

  const setActiveYear = (year: AcademicYear) => {
    setActiveYearState(year);
    localStorage.setItem(storageKey, year);
  };

  return (
    <AcademicYearContext.Provider
      value={{ activeYear, setActiveYear, allYears: getAcademicYears() }}
    >
      {children}
    </AcademicYearContext.Provider>
  );
}

export function useAcademicYear() {
  const ctx = useContext(AcademicYearContext);
  if (!ctx) throw new Error("useAcademicYear must be inside <AcademicYearProvider>");
  return ctx;
}

import {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  type ReactNode,
} from "react";
import {
  onAuthStateChanged,
  signInWithEmailAndPassword,
  createUserWithEmailAndPassword,
  updateProfile,
  signOut,
  type User,
} from "firebase/auth";
import {
  doc,
  getDoc,
  setDoc,
  serverTimestamp,
} from "firebase/firestore";
import { auth, db } from "@/lib/firebase";
import type { UserProfile, Role, School } from "@/types";

interface SignupOptions {
  displayName: string;
  newSchool?: { name: string; nameAr: string };
  schoolId?: string;
  role?: Role;
}

interface AuthContextType {
  user: User | null;
  profile: UserProfile | null;
  school: School | null;
  schoolId: string | null;
  role: Role | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<void>;
  signup: (email: string, password: string, options: SignupOptions) => Promise<void>;
  logout: () => Promise<void>;
  refreshProfile: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [school, setSchool] = useState<School | null>(null);
  const [loading, setLoading] = useState(true);

  // Helper to fetch user profile + school document
  const fetchUserProfileAndSchool = useCallback(async (uid: string) => {
    try {
      console.log("📄 [Firestore] Fetching profile at: users/", uid);
      const profileRef = doc(db, "users", uid);
      const profileSnap = await getDoc(profileRef);

      if (profileSnap.exists()) {
        const data = profileSnap.data() as UserProfile;
        console.log("📄 [Firestore] Profile loaded successfully:", data);
        setProfile(data);

        // Fetch school
        if (data.schoolId) {
          console.log("🏫 [Firestore] Fetching school at: schools/", data.schoolId);
          const schoolRef = doc(db, "schools", data.schoolId);
          const schoolSnap = await getDoc(schoolRef);

          if (schoolSnap.exists()) {
            const schoolData = { id: schoolSnap.id, ...schoolSnap.data() } as School;
            console.log("🏫 [Firestore] School loaded successfully:", schoolData);
            setSchool(schoolData);
          } else {
            console.warn("🏫 [Firestore] School doc missing for ID:", data.schoolId);
            setSchool(null);
          }
        }
      } else {
        console.warn("📄 [Firestore] User profile missing for UID:", uid);
        setProfile(null);
        setSchool(null);
      }
    } catch (err) {
      console.error("❌ [AuthContext] Error fetching profile/school:", err);
      setProfile(null);
      setSchool(null);
    }
  }, []);

  const refreshProfile = useCallback(async () => {
    if (user) {
      await fetchUserProfileAndSchool(user.uid);
    }
  }, [user, fetchUserProfileAndSchool]);

  useEffect(() => {
    const unsub = onAuthStateChanged(auth, async (firebaseUser) => {
      console.log("🔥 [Auth] onAuthStateChanged:", firebaseUser ? firebaseUser.uid : "No user");
      setUser(firebaseUser);

      if (firebaseUser) {
        await fetchUserProfileAndSchool(firebaseUser.uid);
      } else {
        setProfile(null);
        setSchool(null);
      }

      setLoading(false);
    });

    return unsub;
  }, [fetchUserProfileAndSchool]);

  const login = async (email: string, password: string) => {
    const cred = await signInWithEmailAndPassword(auth, email, password);
    if (cred.user) {
      await fetchUserProfileAndSchool(cred.user.uid);
    }
  };

  const signup = async (
    email: string,
    password: string,
    options: SignupOptions
  ) => {
    const { displayName, newSchool, schoolId: existingSchoolId, role = "admin" } = options;

    // 1. Create Firebase Auth user
    const credential = await createUserWithEmailAndPassword(auth, email, password);
    const uid = credential.user.uid;
    setUser(credential.user);

    await updateProfile(credential.user, { displayName });

    let finalSchoolId: string;

    // 2. Create School document if new school
    if (newSchool) {
      finalSchoolId = `${newSchool.name
        .toLowerCase()
        .replace(/\s+/g, "-")
        .replace(/[^a-z0-9-]/g, "")}-${Date.now()}`;

      await setDoc(doc(db, "schools", finalSchoolId), {
        name: newSchool.name,
        nameAr: newSchool.nameAr,
        plan: "free",
        ownerUid: uid,
        createdAt: serverTimestamp(),
      });
      console.log("🏫 [Signup] Created school document:", finalSchoolId);
    } else if (existingSchoolId) {
      finalSchoolId = existingSchoolId;
    } else {
      throw new Error("Either newSchool or schoolId must be provided");
    }

    // 3. Create User Profile document under /users/{uid}
    const profileData = {
      uid,
      email,
      displayName,
      schoolId: finalSchoolId,
      role: newSchool ? ("admin" as Role) : role,
      createdAt: serverTimestamp(),
    };

    await setDoc(doc(db, "users", uid), profileData);
    console.log("📄 [Signup] Created user profile document for UID:", uid);

    // 4. Force immediate state synchronization
    await fetchUserProfileAndSchool(uid);
  };

  const logout = async () => {
    await signOut(auth);
    setUser(null);
    setProfile(null);
    setSchool(null);
  };

  const value: AuthContextType = {
    user,
    profile,
    school,
    schoolId: profile?.schoolId ?? null,
    role: profile?.role ?? null,
    loading,
    login,
    signup,
    logout,
    refreshProfile,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used inside <AuthProvider>");
  return ctx;
}

