import { useEffect, useState, useCallback } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useAcademicYear } from "@/contexts/AcademicYearContext";
import { useTranslation } from "@/lib/i18n";
import {
  fetchCollection,
  addDocument,
  updateDocument,
  deleteDocument,
  orderBy,
  where,
} from "@/lib/firestore-helpers";
import type { Announcement, AnnPriority, AnnouncementTarget } from "@/types";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import RoleGuard from "@/components/RoleGuard";

const PRIORITY_META: Record<AnnPriority, { label: string; icon: string; color: string }> = {
  urgent: { label: "Urgent",  icon: "🔴", color: "bg-red-500/20 text-red-400 border-red-500/30" },
  normal: { label: "Normal",  icon: "🟡", color: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30" },
  info:   { label: "Info",    icon: "🔵", color: "bg-blue-500/20 text-blue-400 border-blue-500/30" },
};

const TARGET_META: Record<AnnouncementTarget, { label: string; icon: string }> = {
  all:     { label: "Everyone",         icon: "👥" },
  teacher: { label: "Teachers Only",    icon: "👨‍🏫" },
  student: { label: "Students & Parents", icon: "👩‍🎓" },
};

const emptyForm = () => ({
  title: "",
  titleEn: "",
  body: "",
  bodyEn: "",
  targetRole: "all" as AnnouncementTarget,
  priority: "normal" as AnnPriority,
  pinned: false,
  expiresAt: "",
});

export default function Announcements() {
  const { schoolId, user, profile } = useAuth();
  const { activeYear } = useAcademicYear();
  const { t } = useTranslation();

  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Announcement | null>(null);
  const [form, setForm] = useState(emptyForm());
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState("");
  const [showArchived, setShowArchived] = useState(false);

  const load = useCallback(async () => {
    if (!schoolId) return;
    setLoading(true);
    try {
      const data = await fetchCollection<Announcement>(schoolId, "announcements", [
        where("academicYear", "==", activeYear),
        orderBy("createdAt", "desc"),
      ]);
      setAnnouncements(data);
    } catch (err) {
      console.error("Error loading announcements:", err);
    } finally {
      setLoading(false);
    }
  }, [schoolId, activeYear]);

  useEffect(() => { load(); }, [load]);

  const openAdd = () => { setEditing(null); setForm(emptyForm()); setModalOpen(true); };
  const openEdit = (ann: Announcement) => {
    setEditing(ann);
    setForm({
      title: ann.title,
      titleEn: ann.titleEn,
      body: ann.body,
      bodyEn: ann.bodyEn,
      targetRole: ann.targetRole,
      priority: ann.priority ?? "normal",
      pinned: ann.pinned ?? false,
      expiresAt: ann.expiresAt ?? "",
    });
    setModalOpen(true);
  };

  const handleSave = async () => {
    if (!schoolId || !form.title || !form.body) return;
    setSaving(true);
    try {
      const data = {
        ...form,
        createdBy: user?.uid ?? "",
        createdByName: profile?.displayName ?? "Admin",
        academicYear: activeYear,
      };
      if (editing) {
        await updateDocument(schoolId, "announcements", editing.id, data);
      } else {
        await addDocument(schoolId, "announcements", data);
      }
      setModalOpen(false);
      await load();
    } catch (err) {
      console.error("Error saving announcement:", err);
    } finally {
      setSaving(false);
    }
  };

  const togglePin = async (ann: Announcement) => {
    if (!schoolId) return;
    await updateDocument(schoolId, "announcements", ann.id, { pinned: !ann.pinned });
    await load();
  };

  const handleDelete = async (ann: Announcement) => {
    if (!schoolId || !confirm(`Delete "${ann.title}"?`)) return;
    try {
      await deleteDocument(schoolId, "announcements", ann.id);
      await load();
    } catch (err) {
      console.error("Error deleting announcement:", err);
    }
  };

  const today = new Date().toISOString().split("T")[0];

  const filtered = announcements
    .filter((ann) => {
      const matchSearch = ann.title.includes(search) || ann.body.includes(search);
      const expired = ann.expiresAt && ann.expiresAt < today;
      const matchArchived = showArchived ? expired : !expired;
      return matchSearch && (showArchived ? true : matchArchived || !ann.expiresAt);
    })
    .sort((a, b) => {
      // Pinned first, then urgent, then by date
      if (a.pinned && !b.pinned) return -1;
      if (!a.pinned && b.pinned) return 1;
      const prioOrder: Record<AnnPriority, number> = { urgent: 0, normal: 1, info: 2 };
      return prioOrder[a.priority ?? "normal"] - prioOrder[b.priority ?? "normal"];
    });

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white">{t("announcements")}</h2>
          <p className="text-sm text-gray-400">{t("schoolNotices")} — {activeYear} ({filtered.length})</p>
        </div>
        <RoleGuard permission="manage:announcements">
          <button
            onClick={openAdd}
            className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white hover:bg-indigo-500 shadow-lg shadow-indigo-500/20 transition-all"
          >
            {t("newAnnouncement")}
          </button>
        </RoleGuard>
      </div>

      {/* Filters */}
      <div className="flex gap-3 flex-wrap">
        <input
          placeholder={t("searchAnnouncements")}
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="flex-1 max-w-xs rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none placeholder:text-gray-600 focus:border-indigo-500"
        />
        <button
          onClick={() => setShowArchived((v) => !v)}
          className={`rounded-lg border px-3 py-2 text-sm font-medium transition-all ${showArchived ? "bg-gray-500/20 text-gray-300 border-gray-500/30" : "border-white/10 text-gray-400 hover:text-white"}`}
        >
          📦 {t("archived")}
        </button>
      </div>

      {/* Announcements grid */}
      {loading ? (
        <div className="py-16 text-center text-gray-500">{t("loading")}</div>
      ) : filtered.length === 0 ? (
        <div className="rounded-2xl border border-white/10 bg-white/5 py-20 text-center text-gray-600">
          {t("noAnnouncementsFound")}
        </div>
      ) : (
        <div className="space-y-4">
          {filtered.map((ann) => {
            const priority = ann.priority ?? "normal";
            const prioMeta = PRIORITY_META[priority];
            const targetMeta = TARGET_META[ann.targetRole ?? "all"];
            const isExpired = ann.expiresAt && ann.expiresAt < today;

            return (
              <div
                key={ann.id}
                className={`relative rounded-2xl border bg-white/5 p-5 transition-all hover:bg-white/8 ${
                  ann.pinned ? "border-amber-500/40 shadow-[0_0_20px_-5px_rgba(245,158,11,0.2)]" : "border-white/10"
                } ${priority === "urgent" ? "border-l-4 border-l-red-500" : priority === "info" ? "border-l-4 border-l-blue-500" : ""}`}
              >
                {/* Badges row */}
                <div className="flex items-center gap-2 mb-3 flex-wrap">
                  {ann.pinned && (
                    <span className="rounded-full border border-amber-500/30 bg-amber-500/20 px-2.5 py-0.5 text-[10px] font-bold text-amber-400">
                      📌 Pinned
                    </span>
                  )}
                  <span className={`rounded-full border px-2.5 py-0.5 text-[10px] font-semibold ${prioMeta.color}`}>
                    {prioMeta.icon} {prioMeta.label}
                  </span>
                  <span className="rounded-full border border-white/10 bg-white/5 px-2.5 py-0.5 text-[10px] text-gray-400">
                    {targetMeta.icon} {targetMeta.label}
                  </span>
                  {isExpired && (
                    <span className="rounded-full border border-gray-500/30 bg-gray-500/20 px-2.5 py-0.5 text-[10px] text-gray-400">
                      Archived
                    </span>
                  )}
                </div>

                <h3 className="text-base font-bold text-white">{ann.title}</h3>
                {ann.titleEn && <p className="text-xs text-gray-500 mt-0.5">{ann.titleEn}</p>}
                <p className="mt-2 text-sm text-gray-300 leading-relaxed line-clamp-3">{ann.body}</p>

                {/* Footer */}
                <div className="mt-4 flex items-center justify-between">
                  <div className="text-xs text-gray-500">
                    {t("postedBy")} <span className="text-gray-400">{ann.createdByName}</span>
                    {ann.expiresAt && (
                      <span className="ml-2">{t("expiresAt")} {ann.expiresAt}</span>
                    )}
                  </div>

                  <div className="flex gap-2">
                    <RoleGuard permission="manage:announcements">
                      <button
                        onClick={() => togglePin(ann)}
                        className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-2.5 py-1 text-xs font-medium text-amber-400 hover:bg-amber-500/20 transition-all"
                      >
                        {ann.pinned ? `📌 ${t("unpin")}` : `📌 ${t("pin")}`}
                      </button>
                      <button
                        onClick={() => openEdit(ann)}
                        className="rounded-lg border border-indigo-500/30 bg-indigo-500/10 px-2.5 py-1 text-xs font-medium text-indigo-400 hover:bg-indigo-500/20 transition-all"
                      >
                        ✏️ {t("edit")}
                      </button>
                      <button
                        onClick={() => handleDelete(ann)}
                        className="rounded-lg border border-rose-500/30 bg-rose-500/10 px-2.5 py-1 text-xs font-medium text-rose-400 hover:bg-rose-500/20 transition-all"
                      >
                        🗑 {t("delete")}
                      </button>
                    </RoleGuard>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* Dialog */}
      <Dialog open={modalOpen} onOpenChange={setModalOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>{editing ? t("editAnnouncement") : t("newAnnouncement")}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 pt-2 max-h-[70vh] overflow-y-auto pr-1">
            <div>
              <label className="block text-xs font-medium text-gray-300 mb-1">{t("title")} (Arabic) *</label>
              <input
                placeholder="عنوان الإعلان"
                value={form.title}
                onChange={(e) => setForm({ ...form, title: e.target.value })}
                className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none focus:border-indigo-500"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-300 mb-1">{t("title")} (English)</label>
              <input
                placeholder="Announcement title"
                value={form.titleEn}
                onChange={(e) => setForm({ ...form, titleEn: e.target.value })}
                className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none focus:border-indigo-500"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-300 mb-1">{t("body")} (Arabic) *</label>
              <textarea
                rows={4}
                placeholder="نص الإعلان..."
                value={form.body}
                onChange={(e) => setForm({ ...form, body: e.target.value })}
                className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none focus:border-indigo-500 resize-none"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-300 mb-1">{t("body")} (English)</label>
              <textarea
                rows={3}
                placeholder="Announcement body..."
                value={form.bodyEn}
                onChange={(e) => setForm({ ...form, bodyEn: e.target.value })}
                className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none focus:border-indigo-500 resize-none"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("priority")}</label>
                <select
                  value={form.priority}
                  onChange={(e) => setForm({ ...form, priority: e.target.value as AnnPriority })}
                  className="w-full rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none"
                >
                  <option value="urgent">🔴 Urgent</option>
                  <option value="normal">🟡 Normal</option>
                  <option value="info">🔵 Info</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("targetAudience")}</label>
                <select
                  value={form.targetRole}
                  onChange={(e) => setForm({ ...form, targetRole: e.target.value as AnnouncementTarget })}
                  className="w-full rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none"
                >
                  <option value="all">👥 Everyone</option>
                  <option value="teacher">👨‍🏫 Teachers Only</option>
                  <option value="student">👩‍🎓 Students & Parents</option>
                </select>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("expiresAt")} ({t("optional")})</label>
                <input
                  type="date"
                  value={form.expiresAt}
                  onChange={(e) => setForm({ ...form, expiresAt: e.target.value })}
                  className="w-full rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none"
                />
              </div>
              <div className="flex items-end">
                <label className="flex items-center gap-3 cursor-pointer p-3 rounded-xl border border-white/10 bg-white/5 w-full hover:bg-white/10 transition-colors">
                  <input
                    type="checkbox"
                    checked={form.pinned}
                    onChange={(e) => setForm({ ...form, pinned: e.target.checked })}
                    className="w-4 h-4 rounded accent-amber-500"
                  />
                  <span className="text-sm text-gray-300">📌 {t("pinned")}</span>
                </label>
              </div>
            </div>
            <div className="flex justify-end gap-3 pt-4 border-t border-white/10">
              <button onClick={() => setModalOpen(false)} className="rounded-lg px-4 py-2 text-sm text-gray-400 hover:text-white">{t("cancel")}</button>
              <button
                onClick={handleSave}
                disabled={saving || !form.title || !form.body}
                className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white hover:bg-indigo-500 disabled:opacity-50 transition-all"
              >
                {saving ? t("publishing") : t("publishAnn")}
              </button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

