import { useEffect, useState, useCallback } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useAcademicYear } from "@/contexts/AcademicYearContext";
import { useTranslation } from "@/lib/i18n";
import {
  fetchCollection,
  batchSetDocuments,
  where,
  orderBy,
} from "@/lib/firestore-helpers";
import type { AttendanceRecord, AttendanceStatus, Student, Class } from "@/types";
import { Combobox } from "@/components/ui/combobox";
import ExcelExport from "@/components/ExcelExport";
import RoleGuard from "@/components/RoleGuard";

const STATUS_OPTIONS: { value: AttendanceStatus; label: string; icon: string; color: string }[] = [
  { value: "present", label: "Present",  icon: "✅", color: "bg-emerald-500/20 text-emerald-400 border-emerald-500/30" },
  { value: "absent",  label: "Absent",   icon: "❌", color: "bg-rose-500/20 text-rose-400 border-rose-500/30" },
  { value: "late",    label: "Late",     icon: "🕐", color: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30" },
  { value: "excused", label: "Excused",  icon: "📋", color: "bg-blue-500/20 text-blue-400 border-blue-500/30" },
];

export default function Attendance() {
  const { schoolId, user } = useAuth();
  const { activeYear } = useAcademicYear();
  const { t } = useTranslation();

  const [classes, setClasses] = useState<Class[]>([]);
  const [students, setStudents] = useState<Student[]>([]);
  const [attendanceMap, setAttendanceMap] = useState<Record<string, AttendanceStatus>>({});
  const [notesMap, setNotesMap] = useState<Record<string, string>>({});
  const [selectedClass, setSelectedClass] = useState("");
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split("T")[0]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [activeTab, setActiveTab] = useState<"today" | "history">("today");
  const [history, setHistory] = useState<AttendanceRecord[]>([]);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [histClass, setHistClass] = useState("");

  useEffect(() => {
    if (!schoolId) return;
    fetchCollection<Class>(schoolId, "classes", [
      where("academicYear", "==", activeYear),
      orderBy("grade"),
    ]).then(setClasses);
  }, [schoolId, activeYear]);

  // Load students and existing attendance when class + date changes
  useEffect(() => {
    if (!schoolId || !selectedClass || !selectedDate) return;
    setLoading(true);
    setSaved(false);

    Promise.all([
      fetchCollection<Student>(schoolId, "students", [
        where("classId", "==", selectedClass),
        orderBy("name"),
      ]),
      fetchCollection<AttendanceRecord>(schoolId, "attendance", [
        where("classId", "==", selectedClass),
        where("date", "==", selectedDate),
        where("academicYear", "==", activeYear),
      ]),
    ]).then(([studs, existing]) => {
      setStudents(studs);
      const am: Record<string, AttendanceStatus> = {};
      const nm: Record<string, string> = {};
      studs.forEach((s) => { am[s.id] = "present"; nm[s.id] = ""; });
      existing.forEach((r) => { am[r.studentId] = r.status; nm[r.studentId] = r.notes || ""; });
      setAttendanceMap(am);
      setNotesMap(nm);
    }).finally(() => setLoading(false));
  }, [schoolId, selectedClass, selectedDate, activeYear]);

  const handleMarkAll = (status: AttendanceStatus) => {
    const newMap: Record<string, AttendanceStatus> = {};
    students.forEach((s) => { newMap[s.id] = status; });
    setAttendanceMap(newMap);
    setSaved(false);
  };

  const handleSave = async () => {
    if (!schoolId || !selectedClass || !selectedDate || students.length === 0) return;
    setSaving(true);
    try {
      const records = students.map((s) => ({
        id: `${s.id}_${selectedDate}`,
        data: {
          studentId: s.id,
          studentName: s.name,
          classId: selectedClass,
          date: selectedDate,
          status: attendanceMap[s.id] ?? "present",
          notes: notesMap[s.id] ?? "",
          recordedBy: user?.uid ?? "",
          academicYear: activeYear,
        },
      }));
      await batchSetDocuments(schoolId, "attendance", records);
      setSaved(true);
    } catch (err) {
      console.error("Error saving attendance:", err);
    } finally {
      setSaving(false);
    }
  };

  // Load history
  const loadHistory = useCallback(async () => {
    if (!schoolId || !histClass) return;
    setHistoryLoading(true);
    try {
      const recs = await fetchCollection<AttendanceRecord>(schoolId, "attendance", [
        where("classId", "==", histClass),
        where("academicYear", "==", activeYear),
        orderBy("date", "desc"),
      ]);
      setHistory(recs);
    } catch (err) {
      console.error("Error loading history:", err);
    } finally {
      setHistoryLoading(false);
    }
  }, [schoolId, histClass, activeYear]);

  useEffect(() => { loadHistory(); }, [loadHistory]);

  const classOptions = classes.map((c) => ({ value: c.id, label: c.name, sublabel: c.nameEn }));

  const presentCount = students.filter((s) => attendanceMap[s.id] === "present").length;
  const absentCount = students.filter((s) => attendanceMap[s.id] === "absent").length;
  const lateCount = students.filter((s) => attendanceMap[s.id] === "late").length;

  const excelData = students.map((s) => ({
    [t("name")]: s.name,
    [t("paymentStatus")]: attendanceMap[s.id] ?? "present",
    [t("notes")]: notesMap[s.id] ?? "",
    [t("selectDate")]: selectedDate,
  }));

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white">{t("attendance")}</h2>
          <p className="text-sm text-gray-400">{t("dailyRegister")} — {activeYear}</p>
        </div>
        <ExcelExport data={excelData} filename="attendance" label={t("exportRegister")} />
      </div>

      {/* Tabs */}
      <div className="flex gap-2 border-b border-white/10">
        {(["today", "history"] as const).map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-4 py-2 text-sm font-medium transition-colors border-b-2 -mb-px ${
              activeTab === tab ? "border-indigo-500 text-white" : "border-transparent text-gray-400 hover:text-white"
            }`}
          >
            {tab === "today" ? `📝 ${t("todayRegister")}` : `📅 ${t("attendanceHistory")}`}
          </button>
        ))}
      </div>

      {activeTab === "today" ? (
        <div className="space-y-6">
          {/* Controls */}
          <div className="flex flex-wrap gap-4">
            <div className="flex-1 min-w-44">
              <label className="block text-xs text-gray-400 mb-1">{t("class")}</label>
              <Combobox
                value={selectedClass}
                onChange={(val) => { setSelectedClass(val); setSaved(false); }}
                placeholder={t("selectClass")}
                options={classOptions}
              />
            </div>
            <div>
              <label className="block text-xs text-gray-400 mb-1">{t("selectDate")}</label>
              <input
                type="date"
                value={selectedDate}
                onChange={(e) => { setSelectedDate(e.target.value); setSaved(false); }}
                className="rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none"
              />
            </div>
          </div>

          {!selectedClass ? (
            <div className="rounded-2xl border border-white/10 bg-white/5 py-20 text-center text-gray-500">
              {t("selectClassFirst")}
            </div>
          ) : loading ? (
            <div className="py-16 text-center text-gray-500">{t("loading")}</div>
          ) : students.length === 0 ? (
            <div className="rounded-2xl border border-white/10 bg-white/5 py-20 text-center text-gray-500">
              {t("noStudentsInClass")}
            </div>
          ) : (
            <>
              {/* Summary Stats */}
              <div className="grid grid-cols-3 gap-4">
                <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 p-4 text-center">
                  <p className="text-2xl font-bold text-white">{presentCount}</p>
                  <p className="text-xs text-emerald-400 mt-1">{t("present")}</p>
                </div>
                <div className="rounded-xl border border-rose-500/30 bg-rose-500/10 p-4 text-center">
                  <p className="text-2xl font-bold text-white">{absentCount}</p>
                  <p className="text-xs text-rose-400 mt-1">{t("absent")}</p>
                </div>
                <div className="rounded-xl border border-yellow-500/30 bg-yellow-500/10 p-4 text-center">
                  <p className="text-2xl font-bold text-white">{lateCount}</p>
                  <p className="text-xs text-yellow-400 mt-1">{t("late")}</p>
                </div>
              </div>

              {/* Bulk actions */}
              <RoleGuard permission="record:attendance">
                <div className="flex gap-2 flex-wrap">
                  <span className="text-xs text-gray-400 self-center me-1">{t("markAllPresent")}:</span>
                  {STATUS_OPTIONS.map((opt) => (
                    <button
                      key={opt.value}
                      onClick={() => handleMarkAll(opt.value)}
                      className={`rounded-lg border px-3 py-1.5 text-xs font-medium transition-all active:scale-95 ${opt.color}`}
                    >
                      {opt.icon} All {opt.label}
                    </button>
                  ))}
                </div>
              </RoleGuard>

              {/* Student list */}
              <div className="space-y-2">
                {students.map((s, i) => {
                  const status = attendanceMap[s.id] ?? "present";
                  const statusMeta = STATUS_OPTIONS.find((o) => o.value === status)!;
                  return (
                    <div
                      key={s.id}
                      className={`rounded-xl border p-3 transition-colors ${statusMeta.color} bg-opacity-5`}
                    >
                      <div className="flex items-center gap-3">
                        <span className="w-8 text-center text-xs font-mono text-gray-500">{i + 1}</span>
                        <p className="flex-1 font-medium text-white">{s.name}</p>
                        {/* Status toggle buttons */}
                        <RoleGuard permission="record:attendance">
                          <div className="flex gap-1.5 flex-wrap">
                            {STATUS_OPTIONS.map((opt) => (
                              <button
                                key={opt.value}
                                onClick={() => { setAttendanceMap((p) => ({ ...p, [s.id]: opt.value })); setSaved(false); }}
                                className={`rounded-lg border px-2 py-1 text-[11px] font-medium transition-all active:scale-95 ${attendanceMap[s.id] === opt.value ? opt.color : "border-white/10 text-gray-600 hover:text-gray-300"}`}
                              >
                                {opt.icon} {opt.label}
                              </button>
                            ))}
                          </div>
                          <input
                            placeholder={t("notes")}
                            value={notesMap[s.id] ?? ""}
                            onChange={(e) => setNotesMap((p) => ({ ...p, [s.id]: e.target.value }))}
                            className="w-32 rounded-lg border border-white/10 bg-black/20 px-2 py-1 text-xs text-gray-300 outline-none placeholder:text-gray-600"
                          />
                        </RoleGuard>
                      </div>
                    </div>
                  );
                })}
              </div>

              <RoleGuard permission="record:attendance">
                <div className="flex items-center gap-4">
                  <button
                    onClick={handleSave}
                    disabled={saving}
                    className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white hover:bg-indigo-500 disabled:opacity-50 transition-all"
                  >
                    {saving ? t("saving") : t("saveAttendance")}
                  </button>
                  {saved && <span className="text-emerald-400 text-sm">{t("savedSuccessfully")}</span>}
                </div>
              </RoleGuard>
            </>
          )}
        </div>
      ) : (
        /* History Tab */
        <div className="space-y-4">
          <div className="flex-1 max-w-xs">
            <label className="block text-xs text-gray-400 mb-1">{t("class")}</label>
            <Combobox
              value={histClass}
              onChange={setHistClass}
              placeholder={t("selectClass")}
              options={classOptions}
            />
          </div>

          {historyLoading ? (
            <p className="text-gray-500 py-10 text-center">{t("loading")}</p>
          ) : history.length === 0 ? (
            <p className="text-gray-600 py-10 text-center">{t("noData")}</p>
          ) : (
            <div className="rounded-2xl border border-white/10 overflow-hidden bg-white/5">
              <table className="w-full text-sm">
                <thead className="border-b border-white/10 bg-gray-900/60">
                  <tr>
                    <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("selectDate")}</th>
                    <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("name")}</th>
                    <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("paymentStatus")}</th>
                    <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("notes")}</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5">
                  {history.slice(0, 100).map((r) => {
                    const opt = STATUS_OPTIONS.find((o) => o.value === r.status)!;
                    return (
                      <tr key={r.id} className="hover:bg-white/5">
                        <td className="px-4 py-3 font-mono text-gray-300 text-xs">{r.date}</td>
                        <td className="px-4 py-3 font-medium text-white">{r.studentName}</td>
                        <td className="px-4 py-3">
                          <span className={`inline-flex rounded-full border px-2.5 py-0.5 text-[11px] font-semibold ${opt.color}`}>
                            {opt.icon} {opt.label}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-gray-500 text-xs">{r.notes || "—"}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

