import { useEffect, useState, useCallback } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useAcademicYear } from "@/contexts/AcademicYearContext";
import { useTranslation } from "@/lib/i18n";
import {
  fetchCollection,
  addDocument,
  updateDocument,
  deleteDocument,
  formatIQD,
  where,
  orderBy,
} from "@/lib/firestore-helpers";
import type { Fee, Student, FeeType, FeeStatus } from "@/types";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Combobox } from "@/components/ui/combobox";
import ExcelExport from "@/components/ExcelExport";
import RoleGuard from "@/components/RoleGuard";
import {
  PieChart, Pie, Cell, Tooltip, ResponsiveContainer, BarChart, Bar,
  XAxis, YAxis, CartesianGrid, Legend,
} from "recharts";

const FEE_TYPES: { value: FeeType; label: string }[] = [
  { value: "tuition",  label: "Tuition Fee" },
  { value: "uniform",  label: "Uniform" },
  { value: "activity", label: "Activities & Trips" },
  { value: "other",    label: "Other Fees" },
];

const FEE_STATUSES: { value: FeeStatus; label: string; color: string }[] = [
  { value: "paid",    label: "Paid",    color: "bg-green-500/20 text-green-400 border-green-500/30" },
  { value: "unpaid",  label: "Unpaid",  color: "bg-red-500/20 text-red-400 border-red-500/30" },
  { value: "partial", label: "Partial", color: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30" },
];

const emptyForm = () => ({
  studentId: "",
  studentName: "",
  classId: "",
  amount: 250000,
  type: "tuition" as FeeType,
  status: "unpaid" as FeeStatus,
  dueDate: new Date().toISOString().split("T")[0],
  notes: "",
  paidAmount: 0,
  paymentMethod: "" as "cash" | "bank_transfer" | "card" | "",
  receiptNumber: "",
});

const PIE_COLORS = ["#10b981", "#6366f1", "#f59e0b", "#e5e7eb"];

export default function Fees() {
  const { schoolId } = useAuth();
  const { activeYear } = useAcademicYear();
  const { t } = useTranslation();

  const [fees, setFees] = useState<Fee[]>([]);
  const [students, setStudents] = useState<Student[]>([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Fee | null>(null);
  const [form, setForm] = useState(emptyForm());
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState("");
  const [filterStatus, setFilterStatus] = useState<string>("all");
  const [showOverdueOnly, setShowOverdueOnly] = useState(false);

  const load = useCallback(async () => {
    if (!schoolId) return;
    setLoading(true);
    try {
      const [feeList, studList] = await Promise.all([
        fetchCollection<Fee>(schoolId, "fees", [
          where("academicYear", "==", activeYear),
          orderBy("createdAt", "desc"),
        ]),
        fetchCollection<Student>(schoolId, "students", [
          where("enrollmentYear", "==", activeYear),
          orderBy("name"),
        ]),
      ]);
      setFees(feeList);
      setStudents(studList);
    } catch (err) {
      console.error("Error loading fees:", err);
    } finally {
      setLoading(false);
    }
  }, [schoolId, activeYear]);

  useEffect(() => { load(); }, [load]);

  const openAdd = () => { setEditing(null); setForm(emptyForm()); setModalOpen(true); };
  const openEdit = (f: Fee) => {
    setEditing(f);
    setForm({
      studentId: f.studentId,
      studentName: f.studentName,
      classId: f.classId,
      amount: f.amount,
      type: f.type,
      status: f.status,
      dueDate: f.dueDate,
      notes: f.notes || "",
      paidAmount: f.paidAmount ?? 0,
      paymentMethod: f.paymentMethod ?? "",
      receiptNumber: f.receiptNumber ?? "",
    });
    setModalOpen(true);
  };

  const handleSave = async () => {
    if (!schoolId || !form.studentId || !form.amount) return;
    setSaving(true);
    try {
      const student = students.find((s) => s.id === form.studentId);
      const data = {
        ...form,
        studentName: student?.name ?? form.studentName,
        classId: student?.classId ?? form.classId,
        paidAt: form.status === "paid" ? new Date().toISOString() : null,
        academicYear: activeYear,
      };

      if (editing) {
        await updateDocument(schoolId, "fees", editing.id, data);
      } else {
        await addDocument(schoolId, "fees", data);
      }
      setModalOpen(false);
      await load();
    } catch (err) {
      console.error("Error saving fee:", err);
    } finally {
      setSaving(false);
    }
  };

  const togglePaidStatus = async (f: Fee) => {
    if (!schoolId) return;
    const nextStatus: FeeStatus = f.status === "paid" ? "unpaid" : "paid";
    await updateDocument(schoolId, "fees", f.id, {
      status: nextStatus,
      paidAt: nextStatus === "paid" ? new Date().toISOString() : null,
    });
    await load();
  };

  const handleDelete = async (f: Fee) => {
    if (!schoolId || !confirm(`Delete fee record for "${f.studentName}"?`)) return;
    try {
      await deleteDocument(schoolId, "fees", f.id);
      await load();
    } catch (err) {
      console.error("Error deleting fee:", err);
    }
  };

  const today = new Date().toISOString().split("T")[0];

  const filtered = fees.filter((f) => {
    const matchSearch = f.studentName.includes(search);
    const matchStatus = filterStatus === "all" || f.status === filterStatus;
    const matchOverdue = !showOverdueOnly || (f.status !== "paid" && f.dueDate < today);
    return matchSearch && matchStatus && matchOverdue;
  });

  const totalAmount = filtered.reduce((acc, f) => acc + (f.amount || 0), 0);
  const paidAmount = filtered.filter((f) => f.status === "paid").reduce((acc, f) => acc + (f.amount || 0), 0);
  const outstanding = totalAmount - paidAmount;
  const overdueCount = fees.filter((f) => f.status !== "paid" && f.dueDate && f.dueDate < today).length;

  // Fee type breakdown for pie
  const typeBreakdown = FEE_TYPES.map((ft) => ({
    name: ft.label,
    value: filtered.filter((f) => f.type === ft.value).reduce((a, f) => a + f.amount, 0),
  })).filter((d) => d.value > 0);

  // Monthly bar data
  const monthMap: Record<string, { paid: number; unpaid: number }> = {};
  for (const f of fees) {
    const key = f.dueDate ? f.dueDate.substring(0, 7) : "—";
    if (!monthMap[key]) monthMap[key] = { paid: 0, unpaid: 0 };
    if (f.status === "paid") monthMap[key].paid += f.amount;
    else monthMap[key].unpaid += f.amount;
  }
  const monthBarData = Object.entries(monthMap)
    .sort(([a], [b]) => a.localeCompare(b))
    .slice(-6)
    .map(([m, v]) => ({ month: m.substring(5), ...v }));

  const studentOptions = students.map((s) => ({
    value: s.id,
    label: s.name,
    sublabel: s.className,
  }));

  const excelData = filtered.map((f) => ({
    [t("student")]: f.studentName,
    [t("feeType")]: FEE_TYPES.find((t) => t.value === f.type)?.label ?? f.type,
    [t("amount")]: f.amount,
    [t("dueDate")]: f.dueDate,
    [t("paymentStatus")]: f.status,
    "Receipt No.": f.receiptNumber ?? "",
    [t("paymentMethod")]: f.paymentMethod ?? "",
    [t("notes")]: f.notes,
  }));

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white">{t("fees")}</h2>
          <p className="text-sm text-gray-400">{t("schoolFees")} — {activeYear} (IQD)</p>
        </div>
        <div className="flex gap-2">
          <ExcelExport data={excelData} filename="fees" label={t("exportFees")} />
          <RoleGuard permission="manage:fees">
            <button onClick={openAdd} className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white hover:bg-indigo-500 shadow-lg shadow-indigo-500/20 transition-all">
              {t("addFeeRecord")}
            </button>
          </RoleGuard>
        </div>
      </div>

      {/* 4 KPI Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="rounded-2xl border border-emerald-500/30 bg-gradient-to-br from-emerald-500/20 to-emerald-600/10 p-5">
          <p className="text-xs font-medium uppercase tracking-widest text-emerald-400">{t("totalCollected")}</p>
          <p className="mt-2 text-2xl font-bold text-white">{formatIQD(paidAmount)}</p>
        </div>
        <div className="rounded-2xl border border-indigo-500/30 bg-gradient-to-br from-indigo-500/20 to-indigo-600/10 p-5">
          <p className="text-xs font-medium uppercase tracking-widest text-indigo-400">{t("totalBilled")}</p>
          <p className="mt-2 text-2xl font-bold text-white">{formatIQD(totalAmount)}</p>
        </div>
        <div className="rounded-2xl border border-rose-500/30 bg-gradient-to-br from-rose-500/20 to-rose-600/10 p-5">
          <p className="text-xs font-medium uppercase tracking-widest text-rose-400">{t("outstanding")}</p>
          <p className="mt-2 text-2xl font-bold text-white">{formatIQD(outstanding)}</p>
        </div>
        <div className="rounded-2xl border border-amber-500/30 bg-gradient-to-br from-amber-500/20 to-amber-600/10 p-5">
          <p className="text-xs font-medium uppercase tracking-widest text-amber-400">⚠ {t("overdue")}</p>
          <p className="mt-2 text-2xl font-bold text-white">{overdueCount}</p>
        </div>
      </div>

      {/* Collection Rate */}
      {totalAmount > 0 && (
        <div className="rounded-2xl border border-white/10 bg-white/5 p-5">
          <div className="flex justify-between mb-2">
            <span className="text-sm font-semibold text-gray-300">{t("collectionRate")}</span>
            <span className="text-sm font-bold text-white">{Math.round((paidAmount / totalAmount) * 100)}%</span>
          </div>
          <div className="h-3 w-full rounded-full bg-white/10 overflow-hidden">
            <div
              className="h-full rounded-full bg-emerald-500 transition-all"
              style={{ width: `${Math.round((paidAmount / totalAmount) * 100)}%` }}
            />
          </div>
        </div>
      )}

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Monthly Revenue */}
        {monthBarData.length > 0 && (
          <div className="rounded-2xl border border-white/10 bg-white/5 p-5">
            <h3 className="text-sm font-semibold text-gray-400 mb-4">📊 {t("monthlyRevenue")}</h3>
            <ResponsiveContainer width="100%" height={180}>
              <BarChart data={monthBarData} barSize={20}>
                <CartesianGrid strokeDasharray="3 3" stroke="#ffffff10" />
                <XAxis dataKey="month" tick={{ fill: "#9ca3af", fontSize: 11 }} />
                <YAxis tick={{ fill: "#9ca3af", fontSize: 10 }} tickFormatter={(v) => `${(v / 1000).toFixed(0)}k`} />
                <Tooltip contentStyle={{ backgroundColor: "#1f2937", border: "1px solid #374151", borderRadius: 8 }} formatter={(v: number) => formatIQD(v)} />
                <Bar dataKey="paid" fill="#10b981" name={t("paid")} radius={[4, 4, 0, 0]} />
                <Bar dataKey="unpaid" fill="#ef4444" name={t("unpaid")} radius={[4, 4, 0, 0]} />
                <Legend wrapperStyle={{ fontSize: 11, color: "#9ca3af" }} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        )}

        {/* Fees by Type */}
        {typeBreakdown.length > 0 && (
          <div className="rounded-2xl border border-white/10 bg-white/5 p-5">
            <h3 className="text-sm font-semibold text-gray-400 mb-4">🍩 {t("feesByType")}</h3>
            <div className="flex items-center gap-4">
              <ResponsiveContainer width={160} height={160}>
                <PieChart>
                  <Pie data={typeBreakdown} cx="50%" cy="50%" innerRadius={40} outerRadius={65} dataKey="value">
                    {typeBreakdown.map((_, i) => <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />)}
                  </Pie>
                  <Tooltip contentStyle={{ backgroundColor: "#1f2937", border: "1px solid #374151", borderRadius: 8 }} formatter={(v: number) => formatIQD(v)} />
                </PieChart>
              </ResponsiveContainer>
              <div className="space-y-2 flex-1">
                {typeBreakdown.map((d, i) => (
                  <div key={d.name} className="flex items-center justify-between text-xs">
                    <div className="flex items-center gap-2">
                      <div className="h-2.5 w-2.5 rounded-full" style={{ backgroundColor: PIE_COLORS[i % PIE_COLORS.length] }} />
                      <span className="text-gray-300">{d.name}</span>
                    </div>
                    <span className="font-bold text-white">{formatIQD(d.value)}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-3">
        <input
          placeholder={t("searchStudents")}
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="flex-1 max-w-xs rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none placeholder:text-gray-600 focus:border-indigo-500"
        />
        <select
          value={filterStatus}
          onChange={(e) => setFilterStatus(e.target.value)}
          className="rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none"
        >
          <option value="all">{t("allStatuses")}</option>
          <option value="paid">{t("paid")}</option>
          <option value="unpaid">{t("unpaid")}</option>
          <option value="partial">{t("partial")}</option>
        </select>
        <button
          onClick={() => setShowOverdueOnly((v) => !v)}
          className={`rounded-lg border px-3 py-2 text-sm font-medium transition-all ${showOverdueOnly ? "bg-amber-500/20 text-amber-400 border-amber-500/30" : "border-white/10 text-gray-400 hover:text-white"}`}
        >
          ⚠ {t("showOverdueOnly")}
        </button>
      </div>

      {/* Table */}
      <div className="rounded-2xl border border-white/10 overflow-hidden bg-white/5 shadow-xl">
        <table className="w-full text-sm text-left">
          <thead className="border-b border-white/10 bg-gray-900/60 backdrop-blur">
            <tr>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("student")}</th>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("feeType")}</th>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("amount")}</th>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("dueDate")}</th>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("paymentStatus")}</th>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">Receipt</th>
              <th className="px-4 py-3.5 text-right text-xs font-bold uppercase tracking-wider text-gray-300">{t("actions")}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5">
            {loading ? (
              <tr><td colSpan={7} className="py-16 text-center text-gray-500">{t("loading")}</td></tr>
            ) : filtered.length === 0 ? (
              <tr><td colSpan={7} className="py-16 text-center text-gray-600">{t("noFeesFound")}</td></tr>
            ) : filtered.map((f) => {
              const statusMeta = FEE_STATUSES.find((s) => s.value === f.status) ?? FEE_STATUSES[1];
              const typeMeta = FEE_TYPES.find((t) => t.value === f.type);
              const isOverdue = f.status !== "paid" && f.dueDate && f.dueDate < today;
              return (
                <tr key={f.id} className={`hover:bg-white/5 transition-colors ${isOverdue ? "bg-amber-500/5" : ""}`}>
                  <td className="px-4 py-3.5 font-medium text-white">
                    {f.studentName}
                    {isOverdue && <span className="ml-2 text-[10px] text-amber-400 border border-amber-500/30 rounded-full px-1.5 py-0.5">⚠ Overdue</span>}
                  </td>
                  <td className="px-4 py-3.5 text-gray-400">{typeMeta?.label || f.type}</td>
                  <td className="px-4 py-3.5 font-bold text-emerald-400 font-mono text-xs">{formatIQD(f.amount)}</td>
                  <td className="px-4 py-3.5 text-gray-400 font-mono text-xs">{f.dueDate || "—"}</td>
                  <td className="px-4 py-3.5">
                    <button
                      onClick={() => togglePaidStatus(f)}
                      className={`inline-flex rounded-full border px-2.5 py-0.5 text-[11px] font-semibold transition-transform active:scale-95 ${statusMeta.color}`}
                    >
                      {statusMeta.label}
                    </button>
                  </td>
                  <td className="px-4 py-3.5 text-gray-500 font-mono text-xs">{f.receiptNumber || "—"}</td>
                  <td className="px-4 py-3.5 text-right">
                    <RoleGuard permission="manage:fees">
                      <div className="flex items-center justify-end gap-2">
                        <button
                          onClick={() => openEdit(f)}
                          className="inline-flex items-center gap-1.5 rounded-lg border border-indigo-500/30 bg-indigo-500/10 px-2.5 py-1 text-xs font-medium text-indigo-400 hover:bg-indigo-500/20 transition-all active:scale-95"
                        >
                          ✏️ {t("edit")}
                        </button>
                        <button
                          onClick={() => handleDelete(f)}
                          className="inline-flex items-center gap-1.5 rounded-lg border border-rose-500/30 bg-rose-500/10 px-2.5 py-1 text-xs font-medium text-rose-400 hover:bg-rose-500/20 transition-all active:scale-95"
                        >
                          🗑 {t("delete")}
                        </button>
                      </div>
                    </RoleGuard>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Dialog */}
      <Dialog open={modalOpen} onOpenChange={setModalOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>{editing ? t("editFee") : t("addFeeRecord")}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 pt-2">
            <div>
              <label className="block text-xs font-medium text-gray-300 mb-1">{t("student")} *</label>
              <Combobox
                value={form.studentId}
                onChange={(val) => setForm({ ...form, studentId: val })}
                placeholder={t("searchStudents")}
                options={studentOptions}
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("feeType")}</label>
                <select
                  value={form.type}
                  onChange={(e) => setForm({ ...form, type: e.target.value as FeeType })}
                  className="w-full rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none"
                >
                  {FEE_TYPES.map((t) => <option key={t.value} value={t.value}>{t.label}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("amount")} (IQD) *</label>
                <input
                  type="number"
                  step={5000}
                  placeholder="250000"
                  value={form.amount}
                  onChange={(e) => setForm({ ...form, amount: Number(e.target.value) })}
                  className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white font-mono outline-none focus:border-indigo-500"
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("dueDate")}</label>
                <input
                  type="date"
                  value={form.dueDate}
                  onChange={(e) => setForm({ ...form, dueDate: e.target.value })}
                  className="w-full rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none"
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("paymentStatus")}</label>
                <select
                  value={form.status}
                  onChange={(e) => setForm({ ...form, status: e.target.value as FeeStatus })}
                  className="w-full rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none"
                >
                  {FEE_STATUSES.map((s) => <option key={s.value} value={s.value}>{s.label}</option>)}
                </select>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("paymentMethod")}</label>
                <select
                  value={form.paymentMethod}
                  onChange={(e) => setForm({ ...form, paymentMethod: e.target.value as typeof form.paymentMethod })}
                  className="w-full rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none"
                >
                  <option value="">—</option>
                  <option value="cash">{t("cash")}</option>
                  <option value="bank_transfer">{t("bankTransfer")}</option>
                  <option value="card">{t("card")}</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("receiptNumber")}</label>
                <input
                  placeholder="RCP-1001"
                  value={form.receiptNumber}
                  onChange={(e) => setForm({ ...form, receiptNumber: e.target.value })}
                  className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white font-mono outline-none focus:border-indigo-500"
                />
              </div>
            </div>
            <div className="flex justify-end gap-3 pt-4 border-t border-white/10">
              <button onClick={() => setModalOpen(false)} className="rounded-lg px-4 py-2 text-sm text-gray-400 hover:text-white">{t("cancel")}</button>
              <button
                onClick={handleSave}
                disabled={saving || !form.studentId || !form.amount}
                className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white hover:bg-indigo-500 disabled:opacity-50 transition-all"
              >
                {saving ? t("saving") : t("saveFee")}
              </button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

