import { useEffect, useState, useCallback } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useAcademicYear } from "@/contexts/AcademicYearContext";
import { useTranslation } from "@/lib/i18n";
import {
  fetchCollection,
  batchSetDocuments,
  formatIQD,
  where,
  orderBy,
} from "@/lib/firestore-helpers";
import type { Student, Class, Subject, Grade, GradeTerm } from "@/types";
import { Combobox } from "@/components/ui/combobox";
import ExcelExport from "@/components/ExcelExport";
import RoleGuard from "@/components/RoleGuard";
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell,
} from "recharts";

const TERMS: { value: GradeTerm; label: string }[] = [
  { value: "first", label: "First Term" },
  { value: "second", label: "Second Term" },
  { value: "final", label: "Final Exam" },
];

const PASS_THRESHOLD = 0.5;

function letterGrade(score: number, max: number): { letter: string; color: string } {
  const pct = (score / max) * 100;
  if (pct >= 90) return { letter: "A+", color: "text-emerald-400" };
  if (pct >= 80) return { letter: "A",  color: "text-emerald-400" };
  if (pct >= 70) return { letter: "B",  color: "text-blue-400" };
  if (pct >= 60) return { letter: "C",  color: "text-yellow-400" };
  if (pct >= 50) return { letter: "D",  color: "text-orange-400" };
  return { letter: "F", color: "text-rose-400" };
}

export default function Grades() {
  const { schoolId, user } = useAuth();
  const { activeYear } = useAcademicYear();
  const { t } = useTranslation();

  const [classes, setClasses] = useState<Class[]>([]);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [students, setStudents] = useState<Student[]>([]);
  const [selectedClass, setSelectedClass] = useState("");
  const [selectedSubject, setSelectedSubject] = useState("");
  const [selectedTerm, setSelectedTerm] = useState<GradeTerm>("first");
  const [scores, setScores] = useState<Record<string, string>>({});
  const [maxScore] = useState(100);
  const [loadingStudents, setLoadingStudents] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    if (!schoolId) return;
    Promise.all([
      fetchCollection<Class>(schoolId, "classes", [where("academicYear", "==", activeYear), orderBy("grade")]),
      fetchCollection<Subject>(schoolId, "subjects", [orderBy("name")]),
    ]).then(([cls, sub]) => { setClasses(cls); setSubjects(sub); });
  }, [schoolId, activeYear]);

  const loadGrades = useCallback(async () => {
    if (!schoolId || !selectedClass || !selectedSubject) return;
    setLoadingStudents(true);
    setSaved(false);

    try {
      const [studs, existingGrades] = await Promise.all([
        fetchCollection<Student>(schoolId, "students", [
          where("classId", "==", selectedClass),
          orderBy("name"),
        ]),
        fetchCollection<Grade>(schoolId, "grades", [
          where("classId", "==", selectedClass),
          where("subjectId", "==", selectedSubject),
          where("term", "==", selectedTerm),
          where("academicYear", "==", activeYear),
        ]),
      ]);

      setStudents(studs);
      const existing: Record<string, string> = {};
      existingGrades.forEach((g) => { existing[g.studentId] = String(g.score); });
      const defaults: Record<string, string> = {};
      studs.forEach((s) => { defaults[s.id] = existing[s.id] ?? ""; });
      setScores(defaults);
    } catch (err) {
      console.error("Error loading grades:", err);
    } finally {
      setLoadingStudents(false);
    }
  }, [schoolId, selectedClass, selectedSubject, selectedTerm, activeYear]);

  useEffect(() => { loadGrades(); }, [loadGrades]);

  const handleSave = async () => {
    if (!schoolId || !selectedClass || !selectedSubject || students.length === 0) return;
    setSaving(true);
    try {
      const subject = subjects.find((s) => s.id === selectedSubject);
      const records = students
        .filter((s) => scores[s.id] !== "")
        .map((s) => ({
          id: `${s.id}_${selectedSubject}_${selectedTerm}_${activeYear}`,
          data: {
            studentId: s.id,
            studentName: s.name,
            subjectId: selectedSubject,
            subjectName: subject?.name ?? "",
            classId: selectedClass,
            term: selectedTerm,
            score: Number(scores[s.id]) || 0,
            maxScore,
            academicYear: activeYear,
            recordedBy: user?.uid ?? "",
          },
        }));
      await batchSetDocuments(schoolId, "grades", records);
      setSaved(true);
    } catch (err) {
      console.error("Error saving grades:", err);
    } finally {
      setSaving(false);
    }
  };

  const getPercent = (score: string) => {
    const n = Number(score);
    if (!score || isNaN(n)) return null;
    return Math.round((n / maxScore) * 100);
  };

  const ready = selectedClass && selectedSubject;

  // Class statistics
  const enteredScores = students.map((s) => Number(scores[s.id])).filter((v) => !isNaN(v) && scores[students.find((st) => st.id !== "")?.id ?? ""] !== "");
  const validScores = students
    .filter((s) => scores[s.id] !== "" && !isNaN(Number(scores[s.id])))
    .map((s) => Number(scores[s.id]));

  const classAvg = validScores.length ? Math.round(validScores.reduce((a, b) => a + b, 0) / validScores.length) : null;
  const classMax = validScores.length ? Math.max(...validScores) : null;
  const classMin = validScores.length ? Math.min(...validScores) : null;
  const passCount = validScores.filter((s) => s / maxScore >= PASS_THRESHOLD).length;

  // Score distribution
  const distBuckets = [
    { label: "0–49", count: validScores.filter((s) => s < 50).length, color: "#ef4444" },
    { label: "50–69", count: validScores.filter((s) => s >= 50 && s < 70).length, color: "#f59e0b" },
    { label: "70–89", count: validScores.filter((s) => s >= 70 && s < 90).length, color: "#6366f1" },
    { label: "90–100", count: validScores.filter((s) => s >= 90).length, color: "#10b981" },
  ];

  // Sorted students for top-3 highlighting
  const sortedStudentIds = [...students]
    .filter((s) => scores[s.id] !== "" && !isNaN(Number(scores[s.id])))
    .sort((a, b) => Number(scores[b.id]) - Number(scores[a.id]))
    .map((s) => s.id);

  const classOptions = classes.map((c) => ({ value: c.id, label: c.name, sublabel: c.nameEn }));
  const subjectOptions = subjects.map((s) => ({ value: s.id, label: s.name, sublabel: s.nameEn }));

  const excelData = students.map((s, i) => {
    const pct = getPercent(scores[s.id] ?? "");
    const { letter } = letterGrade(Number(scores[s.id]) || 0, maxScore);
    return {
      "#": i + 1,
      [t("name")]: s.name,
      [t("score")]: scores[s.id] || "—",
      [t("percentage")]: pct !== null ? `${pct}%` : "—",
      [t("letterGrade")]: scores[s.id] ? letter : "—",
      [t("result")]: pct !== null ? (pct >= 50 ? t("pass") : t("fail")) : "—",
    };
  });

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white">{t("grades")}</h2>
          <p className="text-sm text-gray-400">{t("gradesResults")} — {activeYear}</p>
        </div>
        <ExcelExport data={excelData} filename="grades" label={t("exportGrades")} />
      </div>

      {/* Controls */}
      <div className="flex flex-wrap gap-4">
        <div className="flex-1 min-w-44">
          <label className="block text-xs text-gray-400 mb-1">{t("class")}</label>
          <Combobox
            value={selectedClass}
            onChange={setSelectedClass}
            placeholder={t("selectClass")}
            options={classOptions}
          />
        </div>
        <div className="flex-1 min-w-44">
          <label className="block text-xs text-gray-400 mb-1">{t("subjects")}</label>
          <Combobox
            value={selectedSubject}
            onChange={setSelectedSubject}
            placeholder={t("selectClass")}
            options={subjectOptions}
          />
        </div>
        <div>
          <label className="block text-xs text-gray-400 mb-1">{t("term")}</label>
          <select
            value={selectedTerm}
            onChange={(e) => setSelectedTerm(e.target.value as GradeTerm)}
            className="w-44 rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none"
          >
            {TERMS.map((t) => <option key={t.value} value={t.value}>{t.label}</option>)}
          </select>
        </div>
      </div>

      {!ready ? (
        <div className="rounded-2xl border border-white/10 bg-white/5 py-20 text-center text-gray-500">
          {t("selectClassAndSubject")}
        </div>
      ) : loadingStudents ? (
        <div className="py-16 text-center text-gray-500">{t("loading")}</div>
      ) : students.length === 0 ? (
        <div className="rounded-2xl border border-white/10 bg-white/5 py-20 text-center text-gray-500">
          {t("noStudentsInClass")}
        </div>
      ) : (
        <>
          {/* Class Statistics */}
          {validScores.length > 0 && (
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
              {[
                { label: t("average"),  value: classAvg !== null ? `${Math.round((classAvg / maxScore) * 100)}%` : "—", color: "border-indigo-500/30 bg-indigo-500/10" },
                { label: t("highest"), value: classMax !== null ? `${classMax}/${maxScore}` : "—", color: "border-emerald-500/30 bg-emerald-500/10" },
                { label: t("lowest"),  value: classMin !== null ? `${classMin}/${maxScore}` : "—", color: "border-rose-500/30 bg-rose-500/10" },
                { label: t("pass"),    value: `${passCount}/${validScores.length}`, color: "border-cyan-500/30 bg-cyan-500/10" },
              ].map(({ label, value, color }) => (
                <div key={label} className={`rounded-2xl border p-4 text-center ${color}`}>
                  <p className="text-xl font-bold text-white">{value}</p>
                  <p className="text-xs text-gray-400 mt-1">{label}</p>
                </div>
              ))}
            </div>
          )}

          {/* Score Distribution Chart */}
          {validScores.length > 0 && (
            <div className="rounded-2xl border border-white/10 bg-white/5 p-5">
              <h3 className="text-sm font-semibold text-gray-400 mb-4">Score Distribution</h3>
              <ResponsiveContainer width="100%" height={140}>
                <BarChart data={distBuckets}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#ffffff10" />
                  <XAxis dataKey="label" tick={{ fill: "#9ca3af", fontSize: 11 }} />
                  <YAxis tick={{ fill: "#9ca3af", fontSize: 10 }} allowDecimals={false} />
                  <Tooltip contentStyle={{ backgroundColor: "#1f2937", border: "1px solid #374151", borderRadius: 8 }} />
                  <Bar dataKey="count" radius={[4, 4, 0, 0]}>
                    {distBuckets.map((b) => <Cell key={b.label} fill={b.color} />)}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}

          {/* Grades Table */}
          <div className="rounded-2xl border border-white/10 overflow-hidden bg-white/5">
            <table className="w-full text-sm">
              <thead className="border-b border-white/10 bg-white/5">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-gray-400">#</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-gray-400">{t("student")}</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-gray-400">{t("score")} / {maxScore}</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-gray-400">{t("percentage")}</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-gray-400">{t("letterGrade")}</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-gray-400">{t("result")}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {students.map((s, i) => {
                  const pct = getPercent(scores[s.id] ?? "");
                  const pass = pct !== null && pct >= PASS_THRESHOLD * 100;
                  const { letter, color } = letterGrade(Number(scores[s.id]) || 0, maxScore);
                  const rank = sortedStudentIds.indexOf(s.id);
                  const medal = rank === 0 ? "🥇" : rank === 1 ? "🥈" : rank === 2 ? "🥉" : null;
                  const isFail = pct !== null && pct < 50;
                  return (
                    <tr key={s.id} className={`hover:bg-white/5 ${isFail && scores[s.id] !== "" ? "bg-rose-500/5" : ""}`}>
                      <td className="px-4 py-3 text-gray-500 text-xs">
                        {medal ?? (i + 1)}
                      </td>
                      <td className="px-4 py-3 font-medium text-white">
                        {s.name}
                        {medal && <span className="ml-2 text-xs text-yellow-400">Top {rank + 1}</span>}
                      </td>
                      <td className="px-4 py-3">
                        <RoleGuard permission="record:grades">
                          <input
                            type="number"
                            min={0}
                            max={maxScore}
                            placeholder="—"
                            value={scores[s.id] ?? ""}
                            onChange={(e) => { setScores((p) => ({ ...p, [s.id]: e.target.value })); setSaved(false); }}
                            className="w-24 rounded-lg border border-white/10 bg-white/5 px-3 py-1.5 text-sm text-white font-mono outline-none focus:border-indigo-500"
                          />
                        </RoleGuard>
                        {/* Students can only view */}
                        <RoleGuard permission="view:grades" fallback={null}>
                          {!hasTeachPermission && <span className="font-mono text-white">{scores[s.id] || "—"}</span>}
                        </RoleGuard>
                      </td>
                      <td className="px-4 py-3 text-gray-400">{pct !== null ? `${pct}%` : "—"}</td>
                      <td className={`px-4 py-3 font-bold ${scores[s.id] ? color : "text-gray-600"}`}>
                        {scores[s.id] ? letter : "—"}
                      </td>
                      <td className="px-4 py-3">
                        {pct !== null && (
                          <span className={`inline-flex rounded-full border px-2 py-0.5 text-[10px] font-medium ${pass ? "bg-green-500/20 text-green-400 border-green-500/30" : "bg-red-500/20 text-red-400 border-red-500/30"}`}>
                            {pass ? t("pass") : t("fail")}
                          </span>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>

          <RoleGuard permission="record:grades">
            <div className="flex items-center gap-4">
              <button
                onClick={handleSave}
                disabled={saving}
                className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white hover:bg-indigo-500 disabled:opacity-50 transition-all"
              >
                {saving ? t("saving") : t("saveGrades")}
              </button>
              {saved && <span className="text-green-400 text-sm">{t("gradesSaved")}</span>}
            </div>
          </RoleGuard>
        </>
      )}
    </div>
  );
}

// Helper to avoid runtime error - the RoleGuard handles visibility
const hasTeachPermission = false;

