import { useEffect, useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { useAcademicYear } from "@/contexts/AcademicYearContext";
import { useTranslation } from "@/lib/i18n";
import {
  countDocuments,
  fetchCollection,
  formatIQD,
  where,
  orderBy,
} from "@/lib/firestore-helpers";
import type { Announcement, Fee, AttendanceRecord, Grade, Student } from "@/types";
import {
  BarChart, Bar, LineChart, Line, PieChart, Pie, Cell,
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend,
} from "recharts";
import { format, subDays, parseISO } from "date-fns";

const COLORS = ["#6366f1", "#8b5cf6", "#06b6d4", "#10b981", "#f59e0b", "#ef4444"];

export default function Overview() {
  const { user, profile, school, schoolId } = useAuth();
  const { activeYear } = useAcademicYear();
  const { t, lang } = useTranslation();
  const navigate = useNavigate();

  const firstName =
    (profile?.displayName ?? user?.displayName ?? user?.email ?? "Admin").split(" ")[0];

  const [studentCount, setStudentCount] = useState<number | null>(null);
  const [teacherCount, setTeacherCount] = useState<number | null>(null);
  const [classCount, setClassCount] = useState<number | null>(null);
  const [feesCollected, setFeesCollected] = useState<number | null>(null);
  const [totalBilled, setTotalBilled] = useState<number | null>(null);
  const [recentAnnouncements, setRecentAnnouncements] = useState<Announcement[]>([]);
  const [todayAttendance, setTodayAttendance] = useState<{ present: number; total: number } | null>(null);
  const [loading, setLoading] = useState(true);
  const [attendanceTrend, setAttendanceTrend] = useState<{ date: string; pct: number }[]>([]);
  const [gradeDistribution, setGradeDistribution] = useState<{ name: string; value: number }[]>([]);
  const [topStudents, setTopStudents] = useState<{ name: string; avg: number }[]>([]);
  const [overdueCount, setOverdueCount] = useState(0);
  const [feesByMonth, setFeesByMonth] = useState<{ month: string; paid: number; unpaid: number }[]>([]);

  const loadMetrics = useCallback(async () => {
    if (!schoolId) return;
    setLoading(true);
    const today = new Date().toISOString().split("T")[0];

    try {
      const [sCount, tCount, cCount, allFees, annList, todayAtt, allGrades, allStudents] = await Promise.all([
        countDocuments(schoolId, "students", [where("enrollmentYear", "==", activeYear)]),
        countDocuments(schoolId, "teachers"),
        countDocuments(schoolId, "classes", [where("academicYear", "==", activeYear)]),
        fetchCollection<Fee>(schoolId, "fees", [where("academicYear", "==", activeYear)]),
        fetchCollection<Announcement>(schoolId, "announcements", [
          where("academicYear", "==", activeYear),
          orderBy("createdAt", "desc"),
        ]),
        fetchCollection<AttendanceRecord>(schoolId, "attendance", [
          where("academicYear", "==", activeYear),
          where("date", "==", today),
        ]),
        fetchCollection<Grade>(schoolId, "grades", [where("academicYear", "==", activeYear)]),
        fetchCollection<Student>(schoolId, "students", [where("enrollmentYear", "==", activeYear)]),
      ]);

      setStudentCount(sCount);
      setTeacherCount(tCount);
      setClassCount(cCount);

      // Fees
      const paid = allFees.filter((f) => f.status === "paid").reduce((a, f) => a + f.amount, 0);
      const total = allFees.reduce((a, f) => a + f.amount, 0);
      setFeesCollected(paid);
      setTotalBilled(total);

      // Overdue
      const overdueList = allFees.filter(
        (f) => f.status !== "paid" && f.dueDate && f.dueDate < today
      );
      setOverdueCount(overdueList.length);

      // Announcements
      setRecentAnnouncements(annList.slice(0, 3));

      // Today's attendance
      const presentCount = todayAtt.filter((a) => a.status === "present").length;
      setTodayAttendance({ present: presentCount, total: todayAtt.length });

      // Grade distribution (Pass / Fail)
      const passCount = allGrades.filter((g) => g.score / g.maxScore >= 0.5).length;
      const failCount = allGrades.length - passCount;
      setGradeDistribution([
        { name: t("pass"), value: passCount },
        { name: t("fail"), value: failCount },
      ]);

      // Top students by average grade
      const scoreMap: Record<string, number[]> = {};
      for (const g of allGrades) {
        if (!scoreMap[g.studentId]) scoreMap[g.studentId] = [];
        scoreMap[g.studentId].push(Math.round((g.score / g.maxScore) * 100));
      }
      const studentMap: Record<string, string> = {};
      for (const s of allStudents) studentMap[s.id] = s.name;
      const topList = Object.entries(scoreMap)
        .map(([id, scores]) => ({
          name: studentMap[id] ?? id,
          avg: Math.round(scores.reduce((a, b) => a + b, 0) / scores.length),
        }))
        .sort((a, b) => b.avg - a.avg)
        .slice(0, 5);
      setTopStudents(topList);

      // Fees by month
      const monthMap: Record<string, { paid: number; unpaid: number }> = {};
      for (const f of allFees) {
        const dateKey = f.dueDate ? f.dueDate.substring(0, 7) : "unknown";
        if (!monthMap[dateKey]) monthMap[dateKey] = { paid: 0, unpaid: 0 };
        if (f.status === "paid") monthMap[dateKey].paid += f.amount;
        else monthMap[dateKey].unpaid += f.amount;
      }
      const monthEntries = Object.entries(monthMap)
        .sort(([a], [b]) => a.localeCompare(b))
        .slice(-6)
        .map(([month, vals]) => ({ month: month.substring(5), ...vals }));
      setFeesByMonth(monthEntries);

      // Attendance trend (last 7 days with data)
      const last7 = Array.from({ length: 7 }, (_, i) => {
        const d = subDays(new Date(), i + 1);
        return format(d, "yyyy-MM-dd");
      }).reverse();

      const attTrend = await Promise.all(
        last7.map(async (date) => {
          const recs = await fetchCollection<AttendanceRecord>(schoolId, "attendance", [
            where("academicYear", "==", activeYear),
            where("date", "==", date),
          ]);
          const pct = recs.length === 0 ? 0 : Math.round((recs.filter((r) => r.status === "present").length / recs.length) * 100);
          return { date: date.substring(5), pct };
        })
      );
      setAttendanceTrend(attTrend);

    } catch (err) {
      console.error("Failed to load overview data:", err);
    } finally {
      setLoading(false);
    }
  }, [schoolId, activeYear, t]);

  useEffect(() => {
    loadMetrics();
  }, [loadMetrics]);

  const collectionRate = totalBilled ? Math.round(((feesCollected ?? 0) / totalBilled) * 100) : 0;

  const statCards = [
    {
      label: t("totalStudents"),
      value: loading || studentCount === null ? "..." : studentCount.toLocaleString(),
      color: "from-indigo-500/20 to-indigo-600/10 border-indigo-500/30",
      icon: "👩‍🎓",
    },
    {
      label: t("totalTeachers"),
      value: loading || teacherCount === null ? "..." : teacherCount.toLocaleString(),
      color: "from-violet-500/20 to-violet-600/10 border-violet-500/30",
      icon: "👨‍🏫",
    },
    {
      label: t("totalClasses"),
      value: loading || classCount === null ? "..." : classCount.toLocaleString(),
      color: "from-cyan-500/20 to-cyan-600/10 border-cyan-500/30",
      icon: "🏫",
    },
    {
      label: t("feesCollected"),
      value: loading || feesCollected === null ? "..." : formatIQD(feesCollected),
      color: "from-emerald-500/20 to-emerald-600/10 border-emerald-500/30",
      icon: "💰",
    },
  ];

  return (
    <div className="space-y-8">
      {/* Welcome */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-white">
            {t("welcomeBack")} {firstName} 👋
          </h2>
          <p className="mt-1 text-gray-400">
            {school?.name ?? "..."} — <span className="text-indigo-400 font-semibold">{activeYear}</span>
          </p>
        </div>

        {/* Quick Actions */}
        <div className="flex gap-2 flex-wrap">
          <button
            onClick={() => navigate("/dashboard/attendance")}
            className="rounded-xl border border-indigo-500/30 bg-indigo-500/10 px-3 py-2 text-xs font-medium text-indigo-400 hover:bg-indigo-500/20 transition-all"
          >
            ✅ {t("recordAttendance")}
          </button>
          <button
            onClick={() => navigate("/dashboard/students")}
            className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-xs font-medium text-emerald-400 hover:bg-emerald-500/20 transition-all"
          >
            + {t("addStudent")}
          </button>
          <button
            onClick={() => navigate("/dashboard/announcements")}
            className="rounded-xl border border-violet-500/30 bg-violet-500/10 px-3 py-2 text-xs font-medium text-violet-400 hover:bg-violet-500/20 transition-all"
          >
            📣 {t("publishAnnouncement")}
          </button>
        </div>
      </div>

      {/* Stats grid */}
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        {statCards.map((card) => (
          <div
            key={card.label}
            className={`rounded-2xl border bg-gradient-to-br p-5 ${card.color}`}
          >
            <div className="flex items-center justify-between mb-2">
              <p className="text-xs font-medium uppercase tracking-widest text-gray-400">{card.label}</p>
              <span className="text-2xl">{card.icon}</span>
            </div>
            <p className="text-3xl font-bold text-white">{card.value}</p>
          </div>
        ))}
      </div>

      {/* Overdue + Collection Rate */}
      {!loading && (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div className="rounded-2xl border border-rose-500/20 bg-rose-500/5 p-5">
            <p className="text-xs font-semibold uppercase tracking-wider text-rose-400 mb-2">⚠ {t("overdueFeesAlert")}</p>
            <p className="text-3xl font-bold text-white">{overdueCount}</p>
            <p className="text-sm text-gray-400 mt-1">{t("studentsWithOverdue")}</p>
          </div>
          <div className="rounded-2xl border border-emerald-500/20 bg-emerald-500/5 p-5">
            <div className="flex items-center justify-between mb-3">
              <p className="text-xs font-semibold uppercase tracking-wider text-emerald-400">{t("collectionRate")}</p>
              <span className="text-xl font-bold text-white">{collectionRate}%</span>
            </div>
            <div className="h-3 w-full rounded-full bg-white/10 overflow-hidden">
              <div
                className="h-full rounded-full bg-emerald-500 transition-all duration-700"
                style={{ width: `${collectionRate}%` }}
              />
            </div>
            <p className="text-xs text-gray-400 mt-2">{formatIQD(feesCollected ?? 0)} / {formatIQD(totalBilled ?? 0)}</p>
          </div>
        </div>
      )}

      {/* Charts row */}
      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        {/* Monthly Fees Chart */}
        <div className="rounded-2xl border border-white/10 bg-white/5 p-6">
          <h3 className="mb-4 text-sm font-semibold uppercase tracking-wider text-gray-400">
            📊 {t("monthlyRevenue")} (IQD)
          </h3>
          {feesByMonth.length === 0 ? (
            <p className="text-sm text-gray-600 italic">{t("noData")}</p>
          ) : (
            <ResponsiveContainer width="100%" height={200}>
              <BarChart data={feesByMonth} barSize={20}>
                <CartesianGrid strokeDasharray="3 3" stroke="#ffffff10" />
                <XAxis dataKey="month" tick={{ fill: "#9ca3af", fontSize: 11 }} />
                <YAxis tick={{ fill: "#9ca3af", fontSize: 10 }} tickFormatter={(v) => `${(v / 1000).toFixed(0)}k`} />
                <Tooltip
                  contentStyle={{ backgroundColor: "#1f2937", border: "1px solid #374151", borderRadius: 8 }}
                  formatter={(v: number) => formatIQD(v)}
                />
                <Bar dataKey="paid" fill="#10b981" name={t("paid")} radius={[4, 4, 0, 0]} />
                <Bar dataKey="unpaid" fill="#ef4444" name={t("unpaid")} radius={[4, 4, 0, 0]} />
                <Legend wrapperStyle={{ fontSize: 11, color: "#9ca3af" }} />
              </BarChart>
            </ResponsiveContainer>
          )}
        </div>

        {/* Grade Distribution */}
        <div className="rounded-2xl border border-white/10 bg-white/5 p-6">
          <h3 className="mb-4 text-sm font-semibold uppercase tracking-wider text-gray-400">
            🎓 {t("gradeDistribution")}
          </h3>
          {gradeDistribution.every((d) => d.value === 0) ? (
            <p className="text-sm text-gray-600 italic">{t("noData")}</p>
          ) : (
            <div className="flex items-center gap-6">
              <ResponsiveContainer width={160} height={160}>
                <PieChart>
                  <Pie data={gradeDistribution} cx="50%" cy="50%" innerRadius={45} outerRadius={70} dataKey="value">
                    <Cell fill="#10b981" />
                    <Cell fill="#ef4444" />
                  </Pie>
                  <Tooltip contentStyle={{ backgroundColor: "#1f2937", border: "1px solid #374151", borderRadius: 8 }} />
                </PieChart>
              </ResponsiveContainer>
              <div className="space-y-3 flex-1">
                {gradeDistribution.map((d, i) => (
                  <div key={d.name} className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <div className="h-3 w-3 rounded-full" style={{ backgroundColor: i === 0 ? "#10b981" : "#ef4444" }} />
                      <span className="text-sm text-gray-300">{d.name}</span>
                    </div>
                    <span className="font-bold text-white">{d.value}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Attendance Trend + Top Students */}
      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        {/* Attendance Trend */}
        <div className="rounded-2xl border border-white/10 bg-white/5 p-6">
          <h3 className="mb-4 text-sm font-semibold uppercase tracking-wider text-gray-400">
            📅 {t("attendanceTrend")} (7 {lang === "ar" ? "أيام" : "days"})
          </h3>
          {loading ? (
            <p className="text-sm text-gray-500">{t("loading")}</p>
          ) : (
            <ResponsiveContainer width="100%" height={180}>
              <LineChart data={attendanceTrend}>
                <CartesianGrid strokeDasharray="3 3" stroke="#ffffff10" />
                <XAxis dataKey="date" tick={{ fill: "#9ca3af", fontSize: 11 }} />
                <YAxis domain={[0, 100]} tick={{ fill: "#9ca3af", fontSize: 10 }} unit="%" />
                <Tooltip
                  contentStyle={{ backgroundColor: "#1f2937", border: "1px solid #374151", borderRadius: 8 }}
                  formatter={(v: number) => `${v}%`}
                />
                <Line type="monotone" dataKey="pct" stroke="#6366f1" strokeWidth={2} dot={{ fill: "#6366f1", r: 4 }} name={t("present")} />
              </LineChart>
            </ResponsiveContainer>
          )}
        </div>

        {/* Top Students */}
        <div className="rounded-2xl border border-white/10 bg-white/5 p-6">
          <h3 className="mb-4 text-sm font-semibold uppercase tracking-wider text-gray-400">
            🏆 {t("topStudents")}
          </h3>
          {topStudents.length === 0 ? (
            <p className="text-sm text-gray-600 italic">{t("noData")}</p>
          ) : (
            <div className="space-y-3">
              {topStudents.map((s, i) => (
                <div key={s.name} className="flex items-center gap-3">
                  <span className="w-6 text-center text-sm font-bold" style={{ color: i === 0 ? "#f59e0b" : i === 1 ? "#d1d5db" : i === 2 ? "#b45309" : "#6b7280" }}>
                    {i === 0 ? "🥇" : i === 1 ? "🥈" : i === 2 ? "🥉" : `${i + 1}.`}
                  </span>
                  <p className="flex-1 text-sm font-medium text-white truncate">{s.name}</p>
                  <div className="flex items-center gap-2">
                    <div className="w-24 h-2 rounded-full bg-white/10 overflow-hidden">
                      <div className="h-full rounded-full bg-indigo-500" style={{ width: `${s.avg}%` }} />
                    </div>
                    <span className="text-xs font-bold text-indigo-300 w-10 text-right">{s.avg}%</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Announcements + Today Attendance */}
      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        {/* Recent Announcements */}
        <div className="rounded-2xl border border-white/10 bg-white/5 p-6">
          <h3 className="mb-4 text-sm font-semibold uppercase tracking-wider text-gray-400">
            📣 {t("recentAnnouncements")}
          </h3>
          {loading ? (
            <p className="text-sm text-gray-500">{t("loading")}</p>
          ) : recentAnnouncements.length === 0 ? (
            <p className="text-sm text-gray-600 italic">{t("noAnnouncements")}</p>
          ) : (
            <div className="space-y-3">
              {recentAnnouncements.map((ann) => (
                <div key={ann.id} className="rounded-xl border border-white/5 bg-white/5 p-3">
                  <p className="text-sm font-semibold text-white">{ann.title}</p>
                  <p className="mt-1 text-xs text-gray-400 line-clamp-2">{ann.body}</p>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Today's Attendance */}
        <div className="rounded-2xl border border-white/10 bg-white/5 p-6">
          <h3 className="mb-4 text-sm font-semibold uppercase tracking-wider text-gray-400">
            ✅ {t("todayAttendance")}
          </h3>
          {loading ? (
            <p className="text-sm text-gray-500">{t("loading")}</p>
          ) : !todayAttendance || todayAttendance.total === 0 ? (
            <p className="text-sm text-gray-600 italic">{t("noAttendance")}</p>
          ) : (
            <div className="space-y-4">
              <div className="flex justify-between items-baseline">
                <span className="text-4xl font-bold text-white">
                  {Math.round((todayAttendance.present / todayAttendance.total) * 100)}%
                </span>
                <span className="text-sm text-gray-400">
                  {todayAttendance.present} / {todayAttendance.total}
                </span>
              </div>
              <div className="h-3 w-full rounded-full bg-white/10 overflow-hidden">
                <div
                  className="h-full bg-emerald-500 rounded-full transition-all duration-500"
                  style={{ width: `${Math.round((todayAttendance.present / todayAttendance.total) * 100)}%` }}
                />
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState, useCallback } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { useAcademicYear } from "@/contexts/AcademicYearContext";
import { useTranslation } from "@/lib/i18n";
import { fetchCollection, where, orderBy, formatIQD } from "@/lib/firestore-helpers";
import type { Student, Grade, AttendanceRecord, Fee } from "@/types";
import {
  RadarChart, Radar, PolarGrid, PolarAngleAxis, ResponsiveContainer,
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip,
} from "recharts";

function letterGrade(score: number, max: number): { letter: string; color: string } {
  const pct = (score / max) * 100;
  if (pct >= 90) return { letter: "A+", color: "text-emerald-400" };
  if (pct >= 80) return { letter: "A",  color: "text-emerald-400" };
  if (pct >= 70) return { letter: "B",  color: "text-blue-400" };
  if (pct >= 60) return { letter: "C",  color: "text-yellow-400" };
  if (pct >= 50) return { letter: "D",  color: "text-orange-400" };
  return { letter: "F", color: "text-rose-400" };
}

export default function StudentProfile() {
  const { studentId } = useParams<{ studentId: string }>();
  const { schoolId } = useAuth();
  const { activeYear } = useAcademicYear();
  const { t } = useTranslation();
  const navigate = useNavigate();

  const [student, setStudent] = useState<Student | null>(null);
  const [grades, setGrades] = useState<Grade[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [fees, setFees] = useState<Fee[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<"grades" | "attendance" | "fees">("grades");

  const load = useCallback(async () => {
    if (!schoolId || !studentId) return;
    setLoading(true);
    try {
      const [allStudents, stuGrades, stuAtt, stuFees] = await Promise.all([
        fetchCollection<Student>(schoolId, "students", [where("enrollmentYear", "==", activeYear)]),
        fetchCollection<Grade>(schoolId, "grades", [
          where("studentId", "==", studentId),
          where("academicYear", "==", activeYear),
          orderBy("subjectName"),
        ]),
        fetchCollection<AttendanceRecord>(schoolId, "attendance", [
          where("studentId", "==", studentId),
          where("academicYear", "==", activeYear),
          orderBy("date", "desc"),
        ]),
        fetchCollection<Fee>(schoolId, "fees", [
          where("studentId", "==", studentId),
          where("academicYear", "==", activeYear),
          orderBy("dueDate", "desc"),
        ]),
      ]);
      setStudent(allStudents.find((s) => s.id === studentId) ?? null);
      setGrades(stuGrades);
      setAttendance(stuAtt);
      setFees(stuFees);
    } catch (err) {
      console.error("Error loading student profile:", err);
    } finally {
      setLoading(false);
    }
  }, [schoolId, studentId, activeYear]);

  useEffect(() => { load(); }, [load]);

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center text-gray-500">{t("loading")}</div>
    );
  }

  if (!student) {
    return (
      <div className="flex h-64 flex-col items-center justify-center gap-3 text-gray-500">
        <p>Student not found.</p>
        <button onClick={() => navigate("/dashboard/students")} className="text-indigo-400 underline text-sm">{t("backToStudents")}</button>
      </div>
    );
  }

  // ── Computed stats ──────────────────────────────────────────────────────────
  const presentCount = attendance.filter((a) => a.status === "present").length;
  const absentCount = attendance.filter((a) => a.status === "absent").length;
  const lateCount = attendance.filter((a) => a.status === "late").length;
  const attendancePct = attendance.length ? Math.round((presentCount / attendance.length) * 100) : 0;

  const totalFees = fees.reduce((a, f) => a + f.amount, 0);
  const paidFees = fees.filter((f) => f.status === "paid").reduce((a, f) => a + f.amount, 0);

  // Group grades by subject for radar chart
  const subjectMap: Record<string, number[]> = {};
  for (const g of grades) {
    const key = g.subjectName;
    if (!subjectMap[key]) subjectMap[key] = [];
    subjectMap[key].push(Math.round((g.score / g.maxScore) * 100));
  }
  const radarData = Object.entries(subjectMap).map(([subject, scores]) => ({
    subject,
    avg: Math.round(scores.reduce((a, b) => a + b, 0) / scores.length),
  }));

  // Bar chart: scores by term
  const termMap: Record<string, number[]> = { first: [], second: [], final: [] };
  for (const g of grades) {
    if (termMap[g.term]) termMap[g.term].push(Math.round((g.score / g.maxScore) * 100));
  }
  const termBarData = Object.entries(termMap)
    .filter(([, scores]) => scores.length > 0)
    .map(([term, scores]) => ({
      term: term === "first" ? t("firstTerm") : term === "second" ? t("secondTerm") : t("finalExam"),
      avg: Math.round(scores.reduce((a, b) => a + b, 0) / scores.length),
    }));

  const overallAvg = grades.length
    ? Math.round(grades.reduce((a, g) => a + (g.score / g.maxScore) * 100, 0) / grades.length)
    : null;

  const initials = student.name
    .split(" ")
    .map((n) => n[0])
    .slice(0, 2)
    .join("")
    .toUpperCase();

  return (
    <div className="space-y-6">
      {/* Back + title */}
      <button
        onClick={() => navigate("/dashboard/students")}
        className="flex items-center gap-2 text-sm text-gray-400 hover:text-white transition-colors"
      >
        ← {t("backToStudents")}
      </button>

      {/* Profile header card */}
      <div className="rounded-2xl border border-white/10 bg-white/5 p-6">
        <div className="flex items-start gap-6">
          {/* Avatar */}
          <div className={`flex h-20 w-20 shrink-0 items-center justify-center rounded-2xl text-2xl font-bold text-white shadow-lg ${student.gender === "male" ? "bg-gradient-to-tr from-blue-600 to-indigo-600" : "bg-gradient-to-tr from-pink-500 to-violet-600"}`}>
            {initials}
          </div>

          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-3 flex-wrap">
              <h1 className="text-2xl font-bold text-white">{student.name}</h1>
              <span className={`rounded-full border px-2.5 py-0.5 text-xs font-semibold ${student.gender === "male" ? "bg-blue-500/20 text-blue-400 border-blue-500/30" : "bg-pink-500/20 text-pink-400 border-pink-500/30"}`}>
                {student.gender === "male" ? t("male") : t("female")}
              </span>
              {overallAvg !== null && (
                <span className="rounded-full border border-indigo-500/30 bg-indigo-500/10 px-2.5 py-0.5 text-xs font-semibold text-indigo-300">
                  {t("average")}: {overallAvg}%
                </span>
              )}
            </div>
            {student.nameEn && <p className="text-gray-400 text-sm mt-1">{student.nameEn}</p>}

            <div className="mt-3 grid grid-cols-2 sm:grid-cols-4 gap-4 text-sm">
              <div>
                <p className="text-xs text-gray-500">{t("class")}</p>
                <p className="text-white font-medium">{student.className}</p>
              </div>
              <div>
                <p className="text-xs text-gray-500">{t("dateOfBirth")}</p>
                <p className="text-white font-medium">{student.dateOfBirth || "—"}</p>
              </div>
              <div>
                <p className="text-xs text-gray-500">{t("guardian")}</p>
                <p className="text-white font-medium">{student.guardianName || "—"}</p>
              </div>
              <div>
                <p className="text-xs text-gray-500">{t("phone")}</p>
                <p className="text-white font-mono text-xs">{student.guardianPhone || "—"}</p>
              </div>
              {student.bloodGroup && (
                <div>
                  <p className="text-xs text-gray-500">Blood Group</p>
                  <p className="text-white font-medium">{student.bloodGroup}</p>
                </div>
              )}
              {student.notes && (
                <div className="col-span-2">
                  <p className="text-xs text-gray-500">{t("notes")}</p>
                  <p className="text-gray-300 text-sm">{student.notes}</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Quick stats */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        <div className="rounded-2xl border border-indigo-500/30 bg-indigo-500/10 p-4 text-center">
          <p className="text-2xl font-bold text-white">{overallAvg !== null ? `${overallAvg}%` : "—"}</p>
          <p className="text-xs text-gray-400 mt-1">{t("averageScore")}</p>
        </div>
        <div className="rounded-2xl border border-emerald-500/30 bg-emerald-500/10 p-4 text-center">
          <p className="text-2xl font-bold text-white">{attendancePct}%</p>
          <p className="text-xs text-gray-400 mt-1">{t("present")}</p>
        </div>
        <div className="rounded-2xl border border-cyan-500/30 bg-cyan-500/10 p-4 text-center">
          <p className="text-2xl font-bold text-white">{grades.length}</p>
          <p className="text-xs text-gray-400 mt-1">{t("grades")}</p>
        </div>
        <div className="rounded-2xl border border-violet-500/30 bg-violet-500/10 p-4 text-center">
          <p className="text-2xl font-bold text-white">{formatIQD(paidFees)}</p>
          <p className="text-xs text-gray-400 mt-1">{t("paid")}</p>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 border-b border-white/10">
        {(["grades", "attendance", "fees"] as const).map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-4 py-2 text-sm font-medium transition-colors border-b-2 -mb-px ${
              activeTab === tab
                ? "border-indigo-500 text-white"
                : "border-transparent text-gray-400 hover:text-white"
            }`}
          >
            {t(tab === "grades" ? "grades" : tab === "attendance" ? "attendance" : "fees")}
          </button>
        ))}
      </div>

      {/* Grades Tab */}
      {activeTab === "grades" && (
        <div className="space-y-6">
          {grades.length === 0 ? (
            <p className="py-16 text-center text-gray-600">{t("noData")}</p>
          ) : (
            <>
              {/* Charts row */}
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Radar chart by subject */}
                <div className="rounded-2xl border border-white/10 bg-white/5 p-5">
                  <h3 className="text-sm font-semibold text-gray-400 mb-4">{t("gradesBySubject")}</h3>
                  <ResponsiveContainer width="100%" height={200}>
                    <RadarChart data={radarData}>
                      <PolarGrid stroke="#ffffff20" />
                      <PolarAngleAxis dataKey="subject" tick={{ fill: "#9ca3af", fontSize: 10 }} />
                      <Radar name="Avg" dataKey="avg" stroke="#6366f1" fill="#6366f1" fillOpacity={0.3} />
                      <Tooltip contentStyle={{ backgroundColor: "#1f2937", border: "1px solid #374151", borderRadius: 8 }} formatter={(v: number) => `${v}%`} />
                    </RadarChart>
                  </ResponsiveContainer>
                </div>

                {/* Bar chart by term */}
                {termBarData.length > 0 && (
                  <div className="rounded-2xl border border-white/10 bg-white/5 p-5">
                    <h3 className="text-sm font-semibold text-gray-400 mb-4">{t("averageScore")} {lang === "ar" ? "حسب الفصل" : "by Term"}</h3>
                    <ResponsiveContainer width="100%" height={200}>
                      <BarChart data={termBarData}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#ffffff10" />
                        <XAxis dataKey="term" tick={{ fill: "#9ca3af", fontSize: 11 }} />
                        <YAxis domain={[0, 100]} tick={{ fill: "#9ca3af", fontSize: 10 }} unit="%" />
                        <Tooltip contentStyle={{ backgroundColor: "#1f2937", border: "1px solid #374151", borderRadius: 8 }} formatter={(v: number) => `${v}%`} />
                        <Bar dataKey="avg" fill="#6366f1" radius={[4, 4, 0, 0]} />
                      </BarChart>
                    </ResponsiveContainer>
                  </div>
                )}
              </div>

              {/* Grades table */}
              <div className="rounded-2xl border border-white/10 overflow-hidden bg-white/5">
                <table className="w-full text-sm">
                  <thead className="border-b border-white/10 bg-gray-900/60">
                    <tr>
                      <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("subjects")}</th>
                      <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("term")}</th>
                      <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("score")}</th>
                      <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("percentage")}</th>
                      <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("letterGrade")}</th>
                      <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("result")}</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-white/5">
                    {grades.map((g) => {
                      const pct = Math.round((g.score / g.maxScore) * 100);
                      const { letter, color } = letterGrade(g.score, g.maxScore);
                      const pass = pct >= 50;
                      return (
                        <tr key={g.id} className="hover:bg-white/5">
                          <td className="px-4 py-3 font-medium text-white">{g.subjectName}</td>
                          <td className="px-4 py-3 text-gray-400 text-xs">{g.term === "first" ? t("firstTerm") : g.term === "second" ? t("secondTerm") : t("finalExam")}</td>
                          <td className="px-4 py-3 font-mono text-white">{g.score}/{g.maxScore}</td>
                          <td className="px-4 py-3 text-gray-400">{pct}%</td>
                          <td className={`px-4 py-3 font-bold ${color}`}>{letter}</td>
                          <td className="px-4 py-3">
                            <span className={`inline-flex rounded-full border px-2 py-0.5 text-[10px] font-medium ${pass ? "bg-green-500/20 text-green-400 border-green-500/30" : "bg-red-500/20 text-red-400 border-red-500/30"}`}>
                              {pass ? t("pass") : t("fail")}
                            </span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </>
          )}
        </div>
      )}

      {/* Attendance Tab */}
      {activeTab === "attendance" && (
        <div className="space-y-4">
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
            {[
              { label: t("present"), count: presentCount, color: "border-emerald-500/30 bg-emerald-500/10 text-emerald-400" },
              { label: t("absent"),  count: absentCount,  color: "border-rose-500/30 bg-rose-500/10 text-rose-400" },
              { label: t("late"),    count: lateCount,     color: "border-yellow-500/30 bg-yellow-500/10 text-yellow-400" },
              { label: t("excused"), count: attendance.length - presentCount - absentCount - lateCount, color: "border-blue-500/30 bg-blue-500/10 text-blue-400" },
            ].map(({ label, count, color }) => (
              <div key={label} className={`rounded-2xl border p-4 text-center ${color}`}>
                <p className="text-2xl font-bold text-white">{count}</p>
                <p className="text-xs mt-1">{label}</p>
              </div>
            ))}
          </div>

          <div className="rounded-2xl border border-white/10 overflow-hidden bg-white/5">
            <table className="w-full text-sm">
              <thead className="border-b border-white/10 bg-gray-900/60">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("selectDate")}</th>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("paymentStatus")}</th>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("notes")}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {attendance.length === 0 ? (
                  <tr><td colSpan={3} className="py-10 text-center text-gray-600">{t("noData")}</td></tr>
                ) : attendance.slice(0, 50).map((a) => {
                  const statusColors: Record<string, string> = {
                    present: "bg-green-500/20 text-green-400 border-green-500/30",
                    absent: "bg-red-500/20 text-red-400 border-red-500/30",
                    late: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
                    excused: "bg-blue-500/20 text-blue-400 border-blue-500/30",
                  };
                  return (
                    <tr key={a.id} className="hover:bg-white/5">
                      <td className="px-4 py-3 font-mono text-sm text-gray-300">{a.date}</td>
                      <td className="px-4 py-3">
                        <span className={`inline-flex rounded-full border px-2.5 py-0.5 text-[11px] font-semibold ${statusColors[a.status]}`}>
                          {t(a.status)}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-gray-500 text-xs">{a.notes || "—"}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Fees Tab */}
      {activeTab === "fees" && (
        <div className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="rounded-2xl border border-emerald-500/30 bg-emerald-500/10 p-4">
              <p className="text-xs text-emerald-400 uppercase tracking-wider">{t("totalCollected")}</p>
              <p className="text-2xl font-bold text-white mt-1">{formatIQD(paidFees)}</p>
            </div>
            <div className="rounded-2xl border border-rose-500/30 bg-rose-500/10 p-4">
              <p className="text-xs text-rose-400 uppercase tracking-wider">{t("outstanding")}</p>
              <p className="text-2xl font-bold text-white mt-1">{formatIQD(totalFees - paidFees)}</p>
            </div>
          </div>

          <div className="rounded-2xl border border-white/10 overflow-hidden bg-white/5">
            <table className="w-full text-sm">
              <thead className="border-b border-white/10 bg-gray-900/60">
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("feeType")}</th>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("amount")}</th>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("dueDate")}</th>
                  <th className="px-4 py-3 text-left text-xs font-bold uppercase tracking-wider text-gray-300">{t("paymentStatus")}</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                {fees.length === 0 ? (
                  <tr><td colSpan={4} className="py-10 text-center text-gray-600">{t("noData")}</td></tr>
                ) : fees.map((f) => {
                  const statusColors: Record<string, string> = {
                    paid: "bg-green-500/20 text-green-400 border-green-500/30",
                    unpaid: "bg-red-500/20 text-red-400 border-red-500/30",
                    partial: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
                  };
                  return (
                    <tr key={f.id} className="hover:bg-white/5">
                      <td className="px-4 py-3 text-gray-300">{t(f.type)}</td>
                      <td className="px-4 py-3 font-mono font-bold text-emerald-400 text-xs">{formatIQD(f.amount)}</td>
                      <td className="px-4 py-3 font-mono text-gray-400 text-xs">{f.dueDate || "—"}</td>
                      <td className="px-4 py-3">
                        <span className={`inline-flex rounded-full border px-2.5 py-0.5 text-[11px] font-semibold ${statusColors[f.status]}`}>
                          {t(f.status)}
                        </span>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

