import { useEffect, useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { useAcademicYear } from "@/contexts/AcademicYearContext";
import { useTranslation } from "@/lib/i18n";
import {
  fetchCollection,
  addDocument,
  updateDocument,
  deleteDocument,
  orderBy,
  where,
} from "@/lib/firestore-helpers";
import type { Student, Class } from "@/types";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Combobox } from "@/components/ui/combobox";
import ExcelExport from "@/components/ExcelExport";
import RoleGuard from "@/components/RoleGuard";
import { differenceInYears, parseISO } from "date-fns";

const emptyForm = () => ({
  name: "",
  nameEn: "",
  classId: "",
  gender: "male" as "male" | "female",
  dateOfBirth: "",
  guardianName: "",
  guardianPhone: "",
  address: "",
  bloodGroup: "",
  nationalId: "",
  notes: "",
});

function calcAge(dob: string): string {
  if (!dob) return "—";
  try {
    const age = differenceInYears(new Date(), parseISO(dob));
    return `${age}`;
  } catch {
    return "—";
  }
}

function Avatar({ name, gender }: { name: string; gender: "male" | "female" }) {
  const initials = name
    .split(" ")
    .map((n) => n[0])
    .slice(0, 2)
    .join("")
    .toUpperCase();
  const bg = gender === "male"
    ? "from-blue-600 to-indigo-600"
    : "from-pink-500 to-violet-600";
  return (
    <div className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-gradient-to-tr ${bg} text-xs font-bold text-white shadow`}>
      {initials}
    </div>
  );
}

export default function Students() {
  const { schoolId } = useAuth();
  const { activeYear } = useAcademicYear();
  const { t } = useTranslation();
  const navigate = useNavigate();

  const [students, setStudents] = useState<Student[]>([]);
  const [classes, setClasses] = useState<Class[]>([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Student | null>(null);
  const [form, setForm] = useState(emptyForm());
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState("");
  const [filterClass, setFilterClass] = useState("all");
  const [filterGender, setFilterGender] = useState("all");

  const load = useCallback(async () => {
    if (!schoolId) return;
    setLoading(true);
    try {
      const [studs, cls] = await Promise.all([
        fetchCollection<Student>(schoolId, "students", [
          where("enrollmentYear", "==", activeYear),
          orderBy("name"),
        ]),
        fetchCollection<Class>(schoolId, "classes", [
          where("academicYear", "==", activeYear),
          orderBy("grade"),
        ]),
      ]);
      setStudents(studs);
      setClasses(cls);
    } catch (err) {
      console.error("Error loading students:", err);
    } finally {
      setLoading(false);
    }
  }, [schoolId, activeYear]);

  useEffect(() => { load(); }, [load]);

  const openAdd = () => { setEditing(null); setForm(emptyForm()); setModalOpen(true); };
  const openEdit = (s: Student) => {
    setEditing(s);
    setForm({
      name: s.name,
      nameEn: s.nameEn,
      classId: s.classId,
      gender: s.gender,
      dateOfBirth: s.dateOfBirth,
      guardianName: s.guardianName,
      guardianPhone: s.guardianPhone,
      address: s.address ?? "",
      bloodGroup: s.bloodGroup ?? "",
      nationalId: s.nationalId ?? "",
      notes: s.notes ?? "",
    });
    setModalOpen(true);
  };

  const handleSave = async () => {
    if (!schoolId || !form.name || !form.classId) return;
    setSaving(true);
    try {
      const cls = classes.find((c) => c.id === form.classId);
      const data = {
        ...form,
        className: cls?.name ?? "",
        enrollmentYear: activeYear,
      };
      if (editing) {
        await updateDocument(schoolId, "students", editing.id, data);
      } else {
        await addDocument(schoolId, "students", data);
      }
      setModalOpen(false);
      await load();
    } catch (err) {
      console.error("Error saving student:", err);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (s: Student) => {
    if (!schoolId || !confirm(`Delete student "${s.name}"?`)) return;
    try {
      await deleteDocument(schoolId, "students", s.id);
      await load();
    } catch (err) {
      console.error("Error deleting student:", err);
    }
  };

  const filtered = students.filter((s) => {
    const matchSearch =
      s.name.includes(search) ||
      s.nameEn.toLowerCase().includes(search.toLowerCase()) ||
      (s.guardianName ?? "").includes(search);
    const matchClass = filterClass === "all" || s.classId === filterClass;
    const matchGender = filterGender === "all" || s.gender === filterGender;
    return matchSearch && matchClass && matchGender;
  });

  const maleCount = students.filter((s) => s.gender === "male").length;
  const femaleCount = students.filter((s) => s.gender === "female").length;

  const classOptions = classes.map((c) => ({
    value: c.id,
    label: c.name,
    sublabel: c.nameEn,
  }));

  const excelData = filtered.map((s) => ({
    [t("name")]: s.name,
    "Secondary Name": s.nameEn,
    [t("class")]: s.className,
    [t("gender")]: s.gender === "male" ? t("male") : t("female"),
    [t("dateOfBirth")]: s.dateOfBirth,
    [t("age")]: calcAge(s.dateOfBirth),
    [t("guardian")]: s.guardianName,
    [t("phone")]: s.guardianPhone,
  }));

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white">{t("students")}</h2>
          <p className="text-sm text-gray-400">
            {t("enrolledStudents")} — {activeYear} ({students.length} {t("totalStudents").toLowerCase()})
          </p>
        </div>
        <RoleGuard permission="manage:students">
          <button onClick={openAdd} className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white hover:bg-indigo-500 shadow-lg shadow-indigo-500/20 transition-all">
            {t("addStudentBtn")}
          </button>
        </RoleGuard>
      </div>

      {/* Stats Bar */}
      <div className="grid grid-cols-3 gap-4">
        <div className="rounded-2xl border border-indigo-500/30 bg-indigo-500/10 p-4 text-center">
          <p className="text-2xl font-bold text-white">{students.length}</p>
          <p className="text-xs text-gray-400 mt-1">{t("totalStudents")}</p>
        </div>
        <div className="rounded-2xl border border-blue-500/30 bg-blue-500/10 p-4 text-center">
          <p className="text-2xl font-bold text-white">{maleCount}</p>
          <p className="text-xs text-gray-400 mt-1">{t("male")}</p>
        </div>
        <div className="rounded-2xl border border-pink-500/30 bg-pink-500/10 p-4 text-center">
          <p className="text-2xl font-bold text-white">{femaleCount}</p>
          <p className="text-xs text-gray-400 mt-1">{t("female")}</p>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap gap-3 items-center">
        <input
          placeholder={t("searchStudents")}
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="flex-1 min-w-48 max-w-xs rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none placeholder:text-gray-600 focus:border-indigo-500"
        />
        <select
          value={filterClass}
          onChange={(e) => setFilterClass(e.target.value)}
          className="rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none"
        >
          <option value="all">{t("allClasses")}</option>
          {classes.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
        </select>
        <select
          value={filterGender}
          onChange={(e) => setFilterGender(e.target.value)}
          className="rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none"
        >
          <option value="all">{t("allGenders")}</option>
          <option value="male">{t("male")}</option>
          <option value="female">{t("female")}</option>
        </select>
        <ExcelExport data={excelData} filename="students" label={t("exportExcel")} />
      </div>

      {/* Table */}
      <div className="rounded-2xl border border-white/10 overflow-hidden bg-white/5 shadow-xl">
        <table className="w-full text-sm text-left">
          <thead className="border-b border-white/10 bg-gray-900/60 backdrop-blur">
            <tr>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("name")}</th>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("class")}</th>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("gender")}</th>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("age")}</th>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("guardian")}</th>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("phone")}</th>
