import { useEffect, useState, useCallback } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useTranslation } from "@/lib/i18n";
import {
  fetchCollection,
  addDocument,
  updateDocument,
  deleteDocument,
  orderBy,
} from "@/lib/firestore-helpers";
import type { Teacher, Subject } from "@/types";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import ExcelExport from "@/components/ExcelExport";
import RoleGuard from "@/components/RoleGuard";

const emptyForm = () => ({
  name: "",
  nameEn: "",
  email: "",
  phone: "",
  qualification: "",
  specialization: "",
  joinDate: "",
  status: "active" as "active" | "on-leave" | "resigned",
  notes: "",
  subjectIds: [] as string[],
  classIds: [] as string[],
});

function TeacherAvatar({ name }: { name: string }) {
  const initials = name
    .split(" ")
    .map((n) => n[0])
    .slice(0, 2)
    .join("")
    .toUpperCase();
  return (
    <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-gradient-to-tr from-violet-600 to-indigo-600 text-sm font-bold text-white shadow">
      {initials}
    </div>
  );
}

const STATUS_COLORS: Record<string, string> = {
  active: "bg-emerald-500/20 text-emerald-400 border-emerald-500/30",
  "on-leave": "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
  resigned: "bg-rose-500/20 text-rose-400 border-rose-500/30",
};

export default function Teachers() {
  const { schoolId } = useAuth();
  const { t } = useTranslation();
  const [teachers, setTeachers] = useState<Teacher[]>([]);
  const [allSubjects, setAllSubjects] = useState<Subject[]>([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Teacher | null>(null);
  const [form, setForm] = useState(emptyForm());
  const [saving, setSaving] = useState(false);
  const [search, setSearch] = useState("");
  const [assignModalOpen, setAssignModalOpen] = useState(false);
  const [assignTarget, setAssignTarget] = useState<Teacher | null>(null);
  const [assignSubjectIds, setAssignSubjectIds] = useState<string[]>([]);

  const load = useCallback(async () => {
    if (!schoolId) return;
    setLoading(true);
    try {
      const [data, subj] = await Promise.all([
        fetchCollection<Teacher>(schoolId, "teachers", [orderBy("name")]),
        fetchCollection<Subject>(schoolId, "subjects", [orderBy("name")]),
      ]);
      setTeachers(data);
      setAllSubjects(subj);
    } catch (err) {
      console.error("Error loading teachers:", err);
    } finally {
      setLoading(false);
    }
  }, [schoolId]);

  useEffect(() => { load(); }, [load]);

  const openAdd = () => { setEditing(null); setForm(emptyForm()); setModalOpen(true); };
  const openEdit = (t: Teacher) => {
    setEditing(t);
    setForm({
      name: t.name,
      nameEn: t.nameEn,
      email: t.email,
      phone: t.phone,
      qualification: t.qualification ?? "",
      specialization: t.specialization ?? "",
      joinDate: t.joinDate ?? "",
      status: t.status ?? "active",
      notes: t.notes ?? "",
      subjectIds: t.subjectIds ?? [],
      classIds: t.classIds ?? [],
    });
    setModalOpen(true);
  };

  const openAssign = (teacher: Teacher) => {
    setAssignTarget(teacher);
    setAssignSubjectIds(teacher.subjectIds ?? []);
    setAssignModalOpen(true);
  };

  const handleSaveAssignment = async () => {
    if (!schoolId || !assignTarget) return;
    await updateDocument(schoolId, "teachers", assignTarget.id, { subjectIds: assignSubjectIds });
    setAssignModalOpen(false);
    await load();
  };

  const toggleSubject = (id: string) => {
    setAssignSubjectIds((prev) =>
      prev.includes(id) ? prev.filter((s) => s !== id) : [...prev, id]
    );
  };

  const handleSave = async () => {
    if (!schoolId || !form.name) return;
    setSaving(true);
    try {
      if (editing) {
        await updateDocument(schoolId, "teachers", editing.id, form);
      } else {
        await addDocument(schoolId, "teachers", { ...form });
      }
      setModalOpen(false);
      await load();
    } catch (err) {
      console.error("Error saving teacher:", err);
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (teacher: Teacher) => {
    if (!schoolId || !confirm(`Delete teacher "${teacher.name}"?`)) return;
    try {
      await deleteDocument(schoolId, "teachers", teacher.id);
      await load();
    } catch (err) {
      console.error("Error deleting teacher:", err);
    }
  };

  const filtered = teachers.filter((t) =>
    t.name.includes(search) ||
    t.nameEn.toLowerCase().includes(search.toLowerCase()) ||
    t.email.toLowerCase().includes(search.toLowerCase()) ||
    (t.specialization ?? "").includes(search)
  );

  const excelData = filtered.map((t) => ({
    [t.name]: t.name,
    "Name (Secondary)": t.nameEn,
    [t.email || "Email"]: t.email,
    [t.phone || "Phone"]: t.phone,
    Specialization: t.specialization ?? "",
    Qualification: t.qualification ?? "",
    Status: t.status ?? "active",
    Subjects: (t.subjectIds ?? []).length,
  }));

  const assignedCount = teachers.filter((t) => (t.subjectIds ?? []).length > 0).length;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-white">{t("teachers")}</h2>
          <p className="text-sm text-gray-400">{t("facultyMembers")} ({teachers.length})</p>
        </div>
        <RoleGuard permission="manage:teachers">
          <button onClick={openAdd} className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white hover:bg-indigo-500 shadow-lg shadow-indigo-500/20 transition-all">
            {t("addTeacher")}
          </button>
        </RoleGuard>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        <div className="rounded-2xl border border-violet-500/30 bg-violet-500/10 p-4 text-center">
          <p className="text-2xl font-bold text-white">{teachers.length}</p>
          <p className="text-xs text-gray-400 mt-1">{t("totalTeachers")}</p>
        </div>
        <div className="rounded-2xl border border-emerald-500/30 bg-emerald-500/10 p-4 text-center">
          <p className="text-2xl font-bold text-white">{assignedCount}</p>
          <p className="text-xs text-gray-400 mt-1">{t("assigned")}</p>
        </div>
        <div className="rounded-2xl border border-yellow-500/30 bg-yellow-500/10 p-4 text-center">
          <p className="text-2xl font-bold text-white">{teachers.length - assignedCount}</p>
          <p className="text-xs text-gray-400 mt-1">{t("unassigned")}</p>
        </div>
        <div className="rounded-2xl border border-cyan-500/30 bg-cyan-500/10 p-4 text-center">
          <p className="text-2xl font-bold text-white">{allSubjects.length}</p>
          <p className="text-xs text-gray-400 mt-1">{t("subjects")}</p>
        </div>
      </div>

      {/* Filters */}
      <div className="flex gap-3">
        <input
          placeholder={t("searchTeachers")}
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="flex-1 max-w-xs rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none placeholder:text-gray-600 focus:border-indigo-500"
        />
        <ExcelExport data={excelData} filename="teachers" label={t("exportExcel")} />
      </div>

      {/* Table */}
      <div className="rounded-2xl border border-white/10 overflow-hidden bg-white/5 shadow-xl">
        <table className="w-full text-sm text-left">
          <thead className="border-b border-white/10 bg-gray-900/60 backdrop-blur">
            <tr>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("teachers")}</th>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("email")}</th>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("specialization")}</th>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("subjects")}</th>
              <th className="px-4 py-3.5 text-xs font-bold uppercase tracking-wider text-gray-300">{t("status")}</th>
              <th className="px-4 py-3.5 text-right text-xs font-bold uppercase tracking-wider text-gray-300">{t("actions")}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5">
            {loading ? (
              <tr><td colSpan={6} className="py-16 text-center text-gray-500">{t("loading")}</td></tr>
            ) : filtered.length === 0 ? (
              <tr><td colSpan={6} className="py-16 text-center text-gray-600">{t("noTeachersFound")}</td></tr>
            ) : filtered.map((teacher) => {
              const subjectNames = (teacher.subjectIds ?? [])
                .map((id) => allSubjects.find((s) => s.id === id)?.name)
                .filter(Boolean);
              return (
                <tr key={teacher.id} className="hover:bg-white/5 transition-colors">
                  <td className="px-4 py-3.5">
                    <div className="flex items-center gap-3">
                      <TeacherAvatar name={teacher.name} />
                      <div>
                        <p className="font-medium text-white">{teacher.name}</p>
                        {teacher.nameEn && <p className="text-xs text-gray-500">{teacher.nameEn}</p>}
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-3.5 text-gray-400 font-mono text-xs">{teacher.email || "—"}</td>
                  <td className="px-4 py-3.5 text-gray-400 text-xs">{teacher.specialization || "—"}</td>
                  <td className="px-4 py-3.5">
                    <div className="flex flex-wrap gap-1">
                      {subjectNames.length === 0 ? (
                        <span className="text-gray-600 text-xs">—</span>
                      ) : subjectNames.slice(0, 3).map((name, i) => (
                        <span key={i} className="rounded-full bg-indigo-500/20 border border-indigo-500/30 px-2 py-0.5 text-[10px] font-medium text-indigo-300">
                          {name}
                        </span>
                      ))}
                    </div>
                  </td>
                  <td className="px-4 py-3.5">
                    <span className={`inline-flex rounded-full border px-2.5 py-0.5 text-[11px] font-semibold ${STATUS_COLORS[teacher.status ?? "active"]}`}>
                      {teacher.status === "active" ? t("active") : teacher.status === "on-leave" ? t("onLeave") : t("resigned")}
                    </span>
                  </td>
                  <td className="px-4 py-3.5 text-right">
                    <div className="flex items-center justify-end gap-2">
                      <RoleGuard permission="manage:teachers">
                        <button
                          onClick={() => openAssign(teacher)}
                          className="inline-flex items-center gap-1.5 rounded-lg border border-violet-500/30 bg-violet-500/10 px-2.5 py-1 text-xs font-medium text-violet-400 hover:bg-violet-500/20 transition-all"
                        >
                          📚 {t("assignSubjects")}
                        </button>
                        <button
                          onClick={() => openEdit(teacher)}
                          className="inline-flex items-center gap-1.5 rounded-lg border border-indigo-500/30 bg-indigo-500/10 px-2.5 py-1 text-xs font-medium text-indigo-400 hover:bg-indigo-500/20 transition-all active:scale-95"
                        >
                          ✏️ {t("edit")}
                        </button>
                        <button
                          onClick={() => handleDelete(teacher)}
                          className="inline-flex items-center gap-1.5 rounded-lg border border-rose-500/30 bg-rose-500/10 px-2.5 py-1 text-xs font-medium text-rose-400 hover:bg-rose-500/20 transition-all active:scale-95"
                        >
                          🗑 {t("delete")}
                        </button>
                      </RoleGuard>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Add/Edit Dialog */}
      <Dialog open={modalOpen} onOpenChange={setModalOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>{editing ? t("editTeacher") : t("addTeacher")}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 pt-2 max-h-[70vh] overflow-y-auto pr-1">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("fullName")} *</label>
                <input placeholder="أحمد علي الكريمي" value={form.name}
                  onChange={(e) => setForm({ ...form, name: e.target.value })}
                  className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none focus:border-indigo-500" />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("secondaryName")}</label>
                <input placeholder="A. Al-Karimi" value={form.nameEn}
                  onChange={(e) => setForm({ ...form, nameEn: e.target.value })}
                  className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none focus:border-indigo-500" />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("email")}</label>
                <input type="email" placeholder="teacher@school.com" value={form.email}
                  onChange={(e) => setForm({ ...form, email: e.target.value })}
                  className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none focus:border-indigo-500" />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("phone")}</label>
                <input placeholder="07xx-xxx-xxxx" value={form.phone}
                  onChange={(e) => setForm({ ...form, phone: e.target.value })}
                  className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none focus:border-indigo-500" />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("specialization")}</label>
                <input placeholder="الرياضيات" value={form.specialization}
                  onChange={(e) => setForm({ ...form, specialization: e.target.value })}
                  className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none focus:border-indigo-500" />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("qualification")}</label>
                <select value={form.qualification} onChange={(e) => setForm({ ...form, qualification: e.target.value })}
                  className="w-full rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none">
                  <option value="">—</option>
                  <option value="بكالوريوس">بكالوريوس</option>
                  <option value="ماجستير">ماجستير</option>
                  <option value="دكتوراه">دكتوراه</option>
                  <option value="دبلوم">دبلوم</option>
                </select>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("joinDate")}</label>
                <input type="date" value={form.joinDate}
                  onChange={(e) => setForm({ ...form, joinDate: e.target.value })}
                  className="w-full rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none" />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-300 mb-1">{t("status")}</label>
                <select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value as "active" | "on-leave" | "resigned" })}
                  className="w-full rounded-lg border border-white/10 bg-gray-800 px-3 py-2 text-sm text-white outline-none">
                  <option value="active">{t("active")}</option>
                  <option value="on-leave">{t("onLeave")}</option>
                  <option value="resigned">{t("resigned")}</option>
                </select>
              </div>
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-300 mb-1">{t("notes")} ({t("optional")})</label>
              <textarea rows={2} value={form.notes}
                onChange={(e) => setForm({ ...form, notes: e.target.value })}
                className="w-full rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none focus:border-indigo-500" />
            </div>
            <div className="flex justify-end gap-3 pt-4 border-t border-white/10">
              <button onClick={() => setModalOpen(false)} className="rounded-lg px-4 py-2 text-sm text-gray-400 hover:text-white">{t("cancel")}</button>
              <button onClick={handleSave} disabled={saving || !form.name}
                className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white hover:bg-indigo-500 disabled:opacity-50 transition-all">
                {saving ? t("saving") : t("saveTeacher")}
              </button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Assign Subjects Dialog */}
      <Dialog open={assignModalOpen} onOpenChange={setAssignModalOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{t("assignSubjects")} — {assignTarget?.name}</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 pt-2 max-h-80 overflow-y-auto">
            {allSubjects.map((subj) => (
              <label key={subj.id} className="flex items-center gap-3 cursor-pointer rounded-xl border border-white/5 bg-white/5 p-3 hover:bg-white/10 transition-colors">
                <input
                  type="checkbox"
                  checked={assignSubjectIds.includes(subj.id)}
                  onChange={() => toggleSubject(subj.id)}
                  className="w-4 h-4 rounded accent-indigo-500"
                />
                <div>
                  <p className="text-sm font-medium text-white">{subj.name}</p>
                  {subj.nameEn && <p className="text-xs text-gray-500">{subj.nameEn}</p>}
                </div>
              </label>
            ))}
          </div>
          <div className="flex justify-end gap-3 pt-4 border-t border-white/10">
            <button onClick={() => setAssignModalOpen(false)} className="rounded-lg px-4 py-2 text-sm text-gray-400 hover:text-white">{t("cancel")}</button>
            <button onClick={handleSaveAssignment} className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white hover:bg-indigo-500 transition-all">
              {t("save")}
            </button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}
